window.WOO_POJMY = {"pojem-self-redukce":{"t":"Self-redukce (samo-redukovatelnost)","b":"<p>Technika, jak z algoritmu pro <strong>rozhodovací</strong> verzi problému (černé skříňky, orákula, které odpovídá jen\nANO/NE) získat <strong>konkrétní řešení</strong>: instanci postupně upravujeme (mažeme hrany či vrcholy, přidáváme\nomezení) a orákulem hlídáme, že řešení v ní pořád existuje. Hodnotu optima předtím najdeme binárním\nvyhledáváním přes práh <span class=\"arithmatex\">\\(k\\)</span>. Orákulum se smí ptát jen na instance téhož problému.</p>","u":"@R/ch-ts/ch-ts-optimalizacni-vs-rozhodovaci-problemy.html#ch-ts-od-optima-k-reseni-samo-redukovatelnost"},"pojem-empty":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Empty}\\)</span>","b":"<p><strong>Vstup:</strong> kód Turingova stroje <span class=\"arithmatex\">\\(\\enc{M}\\)</span>.</p>\n<p><strong>Otázka:</strong> je <span class=\"arithmatex\">\\(L_M=\\emptyset\\)</span>, tj. nepřijme <span class=\"arithmatex\">\\(M\\)</span> žádné slovo?</p>\n<p>Jako jazyk: <span class=\"arithmatex\">\\(\\prob{Empty}=\\{\\enc{M} \\mid L_M=\\emptyset\\}\\)</span>.</p>","u":"@R/ch-vycisl/ch-vycisl-ulohy-navic.html#un-2-6"},"pojem-eq":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Eq}\\)</span>","b":"<p><strong>Vstup:</strong> kódy dvou Turingových strojů <span class=\"arithmatex\">\\(\\enc{M_1,M_2}\\)</span>.</p>\n<p><strong>Otázka:</strong> přijímají oba stroje tentýž jazyk, tj. <span class=\"arithmatex\">\\(L_{M_1}=L_{M_2}\\)</span>?</p>\n<p>Jako jazyk: <span class=\"arithmatex\">\\(\\prob{Eq}=\\{\\enc{M_1,M_2} \\mid L_{M_1}=L_{M_2}\\}\\)</span>.</p>","u":"@R/ch-vycisl/ch-vycisl-ulohy-navic.html#un-2-7"},"pojem-square":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Square}\\)</span>","b":"<p><strong>Vstup:</strong> přirozené číslo <span class=\"arithmatex\">\\(n\\)</span>.</p>\n<p><strong>Otázka:</strong> je <span class=\"arithmatex\">\\(n\\)</span> druhou mocninou celého čísla?</p>","u":"@R/ch-cas/ch-cas-ulohy-navic.html#un-3-6"},"pojem-ba":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{BA}\\)</span> (bounded acceptance)","b":"<p><strong>Vstup:</strong> <span class=\"arithmatex\">\\(\\enc{M,x,k}\\)</span> – kód deterministického TS <span class=\"arithmatex\">\\(M\\)</span>, slovo <span class=\"arithmatex\">\\(x\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span> zapsané <strong>binárně</strong>.</p>\n<p><strong>Otázka:</strong> přijme <span class=\"arithmatex\">\\(M\\)</span> slovo <span class=\"arithmatex\">\\(x\\)</span> během nejvýše <span class=\"arithmatex\">\\(k\\)</span> kroků?</p>\n<p><span class=\"arithmatex\">\\(\\prob{BA}_1\\)</span> je totéž s <span class=\"arithmatex\">\\(k\\)</span> zapsaným unárně jako <span class=\"arithmatex\">\\(1^k\\)</span>.</p>","u":"@R/ch-cas/ch-cas-ulohy-navic.html#un-3-8"},"pojem-exact-clique":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Exact Clique}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> má <strong>největší</strong> klika v <span class=\"arithmatex\">\\(G\\)</span> právě <span class=\"arithmatex\">\\(k\\)</span> vrcholů?</p>","u":"@R/ch-np/ch-np-ulohy-navic.html#un-4-3"},"pojem-cnf-taut":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{CNF-TAUT}\\)</span>","b":"<p><strong>Vstup:</strong> formule v CNF.</p>\n<p><strong>Otázka:</strong> je formule tautologie (pravdivá při každém ohodnocení)?</p>","u":"@R/ch-np/ch-np-ulohy-navic.html#un-4-3"},"pojem-dnf-taut":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{DNF-TAUT}\\)</span>","b":"<p><strong>Vstup:</strong> formule v DNF (disjunkce konjunkcí literálů).</p>\n<p><strong>Otázka:</strong> je formule tautologie (pravdivá při každém ohodnocení)?</p>","u":"@R/ch-np/ch-np-ulohy-navic.html#un-4-3"},"pojem-set-cover":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Set Cover}\\)</span>","b":"<p><strong>Vstup:</strong> univerzum <span class=\"arithmatex\">\\(U\\)</span>, systém jeho podmnožin <span class=\"arithmatex\">\\(\\mathcal S=\\{S_1,\\dots,S_m\\}\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> lze vybrat nejvýše <span class=\"arithmatex\">\\(k\\)</span> množin ze <span class=\"arithmatex\">\\(\\mathcal S\\)</span> tak, aby jejich sjednocení bylo celé <span class=\"arithmatex\">\\(U\\)</span>?</p>","u":"@R/ch-is/sec-cv3.html#cv-3-4"},"pojem-fact":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{FACT}\\)</span>","b":"<p><strong>Vstup:</strong> čísla <span class=\"arithmatex\">\\(n\\ge2\\)</span> a <span class=\"arithmatex\">\\(m\\)</span> zapsaná binárně.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(n\\)</span> dělitele <span class=\"arithmatex\">\\(d\\)</span> s <span class=\"arithmatex\">\\(1&lt;d\\le m\\)</span>?</p>","u":"@R/ch-np/ch-np-ulohy-navic.html#un-4-6"},"pojem-lcs":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{nejdelší společné podposloupnosti}\\)</span> (LCS)","b":"<p><strong>Vstup:</strong> binární slova <span class=\"arithmatex\">\\(w_1,\\dots,w_m\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span> zadané unárně (vstup <span class=\"arithmatex\">\\(1^k\\#w_1\\#\\cdots\\#w_m\\)</span>).</p>\n<p><strong>Otázka:</strong> existuje slovo délky <span class=\"arithmatex\">\\(k\\)</span>, které je podposloupností (vznikne vynecháním některých písmen) všech slov <span class=\"arithmatex\">\\(w_1,\\dots,w_m\\)</span>?</p>","u":"@R/ch-np/sec-cv2.html#cv-2-2"},"pojem-bnp":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{BNP}\\)</span>","b":"<p>Stejný jako <span class=\"arithmatex\">\\(\\prob{UNP}\\)</span>, jen číslo <span class=\"arithmatex\">\\(k\\)</span> je zapsané <strong>binárně</strong>.</p>\n<p><strong>Vstup:</strong> kód nedeterministického stroje <span class=\"arithmatex\">\\(M\\)</span>, slovo <span class=\"arithmatex\">\\(x\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span> (binárně).</p>\n<p><strong>Otázka:</strong> přijme <span class=\"arithmatex\">\\(M\\)</span> slovo <span class=\"arithmatex\">\\(x\\)</span> během nejvýše <span class=\"arithmatex\">\\(k\\)</span> kroků?</p>","u":"@R/ch-redukce/ch-redukce-ulohy-navic.html#un-5-5"},"pojem-orakulum":{"t":"Redukce s orákulem","b":"<p>Redukce, která algoritmus pro jiný problém <strong>volá jako podprogram</strong>, klidně víckrát. Ten algoritmus je\n<em>orákulum</em> – černá skříňka, ze které nás zajímá jen odpověď. Karpova (polynomiální) redukce je zvláštní\npřípad: orákulum se ptáme jen jednou a jeho odpověď vracíme beze změny.</p>","u":"@R/ch-graf/ch-graf-redukce-s-orakulem-a-vycislitelnost.html#fig-graf-redukce-s-orakulem"},"pojem-formula-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Formula-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> výroková formule <span class=\"arithmatex\">\\(\\varphi\\)</span> ze spojek <span class=\"arithmatex\">\\(\\lnot\\)</span>, <span class=\"arithmatex\">\\(\\land\\)</span>, <span class=\"arithmatex\">\\(\\lor\\)</span> a závorek, libovolně vnořená (nemusí být v CNF).</p>\n<p><strong>Otázka:</strong> existuje ohodnocení proměnných, při kterém je <span class=\"arithmatex\">\\(\\varphi\\)</span> pravdivá?</p>","u":"@R/ch-cook/ch-cook-ulohy-navic.html#un-6-1"},"pojem-non-equivalence":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Non-Equivalence}\\)</span>","b":"<p><strong>Vstup:</strong> dvě formule <span class=\"arithmatex\">\\(\\varphi\\)</span> a <span class=\"arithmatex\">\\(\\psi\\)</span> v CNF nad proměnnými <span class=\"arithmatex\">\\(x_1,\\dots,x_n\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, při kterém má <span class=\"arithmatex\">\\(\\varphi\\)</span> jinou pravdivostní hodnotu než <span class=\"arithmatex\">\\(\\psi\\)</span> (formule nejsou ekvivalentní)?</p>","u":"@R/ch-cook/ch-cook-ulohy-navic.html#un-6-2"},"pojem-max-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{MAX-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v CNF s klauzulemi <span class=\"arithmatex\">\\(C_1,\\dots,C_m\\)</span> (každá má aspoň jeden literál) a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, které splní <strong>aspoň <span class=\"arithmatex\">\\(k\\)</span></strong> klauzulí?</p>","u":"@R/ch-cook/ch-cook-ulohy-navic.html#un-6-3"},"pojem-half-max-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Half-MAX-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v CNF s klauzulemi <span class=\"arithmatex\">\\(C_1,\\dots,C_m\\)</span> (každá má aspoň jeden literál).</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, které splní aspoň <span class=\"arithmatex\">\\(\\lceil m/2\\rceil\\)</span> klauzulí? (Je to <span class=\"arithmatex\">\\(\\prob{MAX-SAT}\\)</span> s pevným prahem.)</p>","u":"@R/ch-cook/ch-cook-ulohy-navic.html#un-6-3"},"pojem-half-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Half-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v CNF s proměnnými <span class=\"arithmatex\">\\(x_1,\\dots,x_N\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, které <span class=\"arithmatex\">\\(\\varphi\\)</span> splňuje a při kterém má <strong>přesně <span class=\"arithmatex\">\\(N/2\\)</span></strong> proměnných hodnotu <span class=\"arithmatex\">\\(1\\)</span>?</p>","u":"@R/ch-cook/ch-cook-ulohy-navic.html#un-6-4"},"pojem-another-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Another-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v CNF a ohodnocení <span class=\"arithmatex\">\\(h\\)</span>, které <span class=\"arithmatex\">\\(\\varphi\\)</span> splňuje.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(\\varphi\\)</span> ještě jiné splňující ohodnocení (různé od <span class=\"arithmatex\">\\(h\\)</span>)?</p>","u":"@R/ch-cook/ch-cook-ulohy-navic.html#un-6-5"},"pojem-min-ones-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Min-Ones SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v CNF nad <span class=\"arithmatex\">\\(x_1,\\dots,x_n\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, které <span class=\"arithmatex\">\\(\\varphi\\)</span> splňuje a má <strong>nejvýše <span class=\"arithmatex\">\\(k\\)</span></strong> proměnných rovných <span class=\"arithmatex\">\\(1\\)</span>?</p>","u":"@R/ch-cook/ch-cook-ulohy-navic.html#un-6-6"},"pojem-3sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{3-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule v 3-CNF, tj. v CNF, kde má každá klauzule <strong>přesně 3</strong> literály.</p>\n<p><strong>Otázka:</strong> je formule splnitelná?</p>","u":"@R/ch-sat/ch-sat-sat-3-sat.html#red-sat3sat"},"pojem-pozitivni-nae":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Pozitivní NAE-3-SAT}\\)</span>","b":"<p><span class=\"arithmatex\">\\(\\prob{NAE-3-SAT}\\)</span> bez negací (pozitivní, monotónní): všechny literály jsou kladné.</p>\n<p><strong>Vstup:</strong> formule v 3-CNF bez negací.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, při kterém v žádné klauzuli nemají všechny tři literály stejnou hodnotu?</p>","u":"@R/ch-sat/ch-sat-nae-3-sat-not-all-equal.html#ch-sat-pozitivni-nae-3-sat"},"pojem-double-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Double-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v CNF.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(\\varphi\\)</span> <strong>aspoň dvě různá</strong> splňující ohodnocení?</p>","u":"@R/ch-sat/ch-sat-ulohy-navic.html#un-7-4"},"pojem-e3sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{E3-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule v CNF, kde každá klauzule obsahuje <strong>přesně tři literály s navzájem různými\nproměnnými</strong> (ani dvakrát týž literál, ani <span class=\"arithmatex\">\\(x\\)</span> a <span class=\"arithmatex\">\\(\\lnot x\\)</span> v téže klauzuli).</p>\n<p><strong>Otázka:</strong> je formule splnitelná?</p>","u":"@R/ch-sat/ch-sat-ulohy-navic.html#un-7-5"},"pojem-3sat-3":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{3-SAT-3}\\)</span>","b":"<p><strong>Vstup:</strong> formule v CNF, ve které má každá klauzule <strong>nejvýše tři</strong> literály a každá proměnná se\nvyskytuje <strong>nejvýše třikrát</strong> (výskyty <span class=\"arithmatex\">\\(x\\)</span> a <span class=\"arithmatex\">\\(\\lnot x\\)</span> se počítají dohromady).</p>\n<p><strong>Otázka:</strong> je formule splnitelná?</p>","u":"@R/ch-sat/ch-sat-ulohy-navic.html#un-7-6"},"pojem-monotonni-3sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Monotónní 3-SAT}\\)</span>","b":"<p>Klauzule je <em>monotónní</em>, jsou-li všechny její literály kladné, nebo všechny záporné.</p>\n<p><strong>Vstup:</strong> 3-CNF formule (3 literály v klauzuli, opakování dovoleno), jejíž každá klauzule je monotónní.</p>\n<p><strong>Otázka:</strong> je formule splnitelná?</p>","u":"@R/ch-sat/ch-sat-ulohy-navic.html#un-7-7"},"pojem-set-splitting":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Set Splitting}\\)</span>","b":"<p><strong>Vstup:</strong> konečná množina <span class=\"arithmatex\">\\(U\\)</span> a systém jejích podmnožin <span class=\"arithmatex\">\\(S_1,\\dots,S_r\\)</span>.</p>\n<p><strong>Otázka:</strong> lze prvky <span class=\"arithmatex\">\\(U\\)</span> obarvit dvěma barvami tak, aby žádná z množin <span class=\"arithmatex\">\\(S_j\\)</span> nebyla jednobarevná?</p>","u":"@R/ch-sat/ch-sat-ulohy-navic.html#un-7-1"},"pojem-flip-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Flip-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v CNF.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení <span class=\"arithmatex\">\\(h\\)</span> takové, že formuli <span class=\"arithmatex\">\\(\\varphi\\)</span> splňuje <span class=\"arithmatex\">\\(h\\)</span> <strong>i</strong> překlopené ohodnocení <span class=\"arithmatex\">\\(\\bar h\\)</span> (všechny hodnoty prohozené)?</p>","u":"@R/ch-sat/ch-sat-ulohy-navic.html#un-7-2"},"pojem-gadget":{"t":"Gadget","b":"<p>Lokální struktura (podgraf, rovnice, podmínka), ze které stavíme redukci. Simuluje chování prvků\npůvodního problému (proměnných, klauzulí) – např. gadget proměnné vynutí výběr ohodnocení, gadget\nklauzule její splnění.</p>","u":"@R/ch-is/ch-is-anatomie-redukci.html#fig-is-dva-smery"},"pojem-subgraph-isomorphism":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Subgraph Isomorphism}\\)</span>","b":"<p><strong>Vstup:</strong> grafy <span class=\"arithmatex\">\\(G\\)</span> a <span class=\"arithmatex\">\\(H\\)</span>.</p>\n<p><strong>Otázka:</strong> obsahuje <span class=\"arithmatex\">\\(G\\)</span> podgraf izomorfní s <span class=\"arithmatex\">\\(H\\)</span>? (Tj. existuje prosté zobrazení <span class=\"arithmatex\">\\(f\\colon V(H)\\to V(G)\\)</span>\ntakové, že pro každou hranu <span class=\"arithmatex\">\\(\\{u,v\\}\\in E(H)\\)</span> je <span class=\"arithmatex\">\\(\\{f(u),f(v)\\}\\in E(G)\\)</span>?)</p>","u":"@R/ch-is/sec-cv3.html#cv-3-2"},"pojem-half-clique":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Half-Clique}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span> na <span class=\"arithmatex\">\\(n\\)</span> vrcholech.</p>\n<p><strong>Otázka:</strong> obsahuje <span class=\"arithmatex\">\\(G\\)</span> kliku velikosti alespoň <span class=\"arithmatex\">\\(n/2\\)</span>?</p>","u":"@R/ch-is/sec-cv3.html#cv-3-3"},"pojem-fvs":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Feedback Vertex Set}\\)</span>","b":"<p><strong>Vstup:</strong> neorientovaný jednoduchý graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(F\\subseteq V\\)</span>, <span class=\"arithmatex\">\\(|F|\\le k\\)</span>, taková, že graf <span class=\"arithmatex\">\\(G-F\\)</span> neobsahuje žádnou kružnici (je to les)?</p>","u":"@R/ch-is/sec-cv3.html#cv-3-5"},"pojem-dominating-set":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Dominating Set}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(D\\subseteq V\\)</span>, <span class=\"arithmatex\">\\(|D|\\le k\\)</span>, taková, že každý vrchol mimo <span class=\"arithmatex\">\\(D\\)</span> má souseda v <span class=\"arithmatex\">\\(D\\)</span>?</p>","u":"@R/ch-is/sec-cv3.html#cv-3-6"},"pojem-set-packing":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Set Packing}\\)</span> (balení množin)","b":"<p><strong>Vstup:</strong> konečné univerzum <span class=\"arithmatex\">\\(U\\)</span>, systém podmnožin <span class=\"arithmatex\">\\(S_1,\\dots,S_r\\subseteq U\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> lze ze systému vybrat <span class=\"arithmatex\">\\(k\\)</span> množin, které jsou po dvou disjunktní?</p>","u":"@R/ch-is/ch-is-ulohy-navic.html#un-8-4"},"pojem-dense-subgraph":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Dense Subgraph}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a čísla <span class=\"arithmatex\">\\(k\\)</span>, <span class=\"arithmatex\">\\(l\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(S\\subseteq V\\)</span>, <span class=\"arithmatex\">\\(|S|=k\\)</span>, takové, že indukovaný podgraf <span class=\"arithmatex\">\\(G[S]\\)</span> má <strong>alespoň</strong> <span class=\"arithmatex\">\\(l\\)</span> hran?</p>","u":"@R/ch-is/ch-is-ulohy-navic.html#un-8-5"},"pojem-sparse-subgraph":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Sparse Subgraph}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a čísla <span class=\"arithmatex\">\\(k\\)</span>, <span class=\"arithmatex\">\\(l\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(S\\subseteq V\\)</span>, <span class=\"arithmatex\">\\(|S|=k\\)</span>, takové, že indukovaný podgraf <span class=\"arithmatex\">\\(G[S]\\)</span> má <strong>nejvýše</strong> <span class=\"arithmatex\">\\(l\\)</span> hran?</p>","u":"@R/ch-is/ch-is-ulohy-navic.html#un-8-5"},"pojem-min-ones-monotone-2sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Min-Ones Monotone 2-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v KNF nad proměnnými <span class=\"arithmatex\">\\(y_1,\\dots,y_N\\)</span>, v níž má každá klauzule tvar\n<span class=\"arithmatex\">\\((y_i\\lor y_j)\\)</span> pro dvě různé proměnné (žádné negace), a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení splňující <span class=\"arithmatex\">\\(\\varphi\\)</span>, v němž je <strong>nejvýše <span class=\"arithmatex\">\\(k\\)</span></strong> proměnných rovno <span class=\"arithmatex\">\\(1\\)</span>?</p>","u":"@R/ch-is/ch-is-ulohy-navic.html#un-8-6"},"pojem-clique-and-is":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Clique and IS}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span> (binárně).</p>\n<p><strong>Otázka:</strong> obsahuje <span class=\"arithmatex\">\\(G\\)</span> kliku velikosti <span class=\"arithmatex\">\\(k\\)</span> <strong>a zároveň</strong> nezávislou množinu velikosti <span class=\"arithmatex\">\\(k\\)</span>?</p>","u":"@R/ch-is/ch-is-ulohy-navic.html#un-8-7"},"pojem-partial-vc":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Partial VC}\\)</span> (částečné vrcholové pokrytí)","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a čísla <span class=\"arithmatex\">\\(k\\)</span> a <span class=\"arithmatex\">\\(t\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje množina <span class=\"arithmatex\">\\(C\\subseteq V\\)</span>, <span class=\"arithmatex\">\\(|C|\\le k\\)</span>, která pokrývá aspoň <span class=\"arithmatex\">\\(t\\)</span> hran (aspoň <span class=\"arithmatex\">\\(t\\)</span> hran má v <span class=\"arithmatex\">\\(C\\)</span> aspoň jeden konec)?</p>","u":"@R/ch-is/ch-is-ulohy-navic.html#un-8-1"},"pojem-triangle-free-is":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Triangle-free IS}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span> <strong>bez trojúhelníků</strong> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(G\\)</span> nezávislou množinu velikosti aspoň <span class=\"arithmatex\">\\(k\\)</span>?</p>","u":"@R/ch-is/ch-is-ulohy-navic.html#un-8-8"},"pojem-2coloring":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{2-Coloring}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span>.</p>\n<p><strong>Otázka:</strong> lze vrcholy grafu <span class=\"arithmatex\">\\(G\\)</span> obarvit dvěma barvami tak, aby žádná hrana nespojovala dva vrcholy\nstejné barvy?</p>\n<p>Na rozdíl od <span class=\"arithmatex\">\\(\\prob{3-Coloring}\\)</span> je v <span class=\"arithmatex\">\\(\\PP\\)</span>.</p>","u":"@R/ch-zoo/ch-zoo-ulohy-navic.html#ch-zoo-ulohy-navic-nez-zacnes"},"pojem-clique-cover":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Clique Cover}\\)</span> (pokrytí klikami)","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> lze <span class=\"arithmatex\">\\(V\\)</span> rozdělit na nejvýše <span class=\"arithmatex\">\\(k\\)</span> disjunktních množin <span class=\"arithmatex\">\\(Q_1,\\dots,Q_j\\)</span> (<span class=\"arithmatex\">\\(j\\le k\\)</span>) tak, aby každá\n<span class=\"arithmatex\">\\(Q_i\\)</span> byla klika?</p>","u":"@R/ch-zoo/ch-zoo-ulohy-navic.html#un-9-5"},"pojem-max-bisection":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Max Bisection}\\)</span>","b":"<p><em>Bisekce</em> grafu s <span class=\"arithmatex\">\\(2h\\)</span> vrcholy je rozdělení <span class=\"arithmatex\">\\(V=A\\cup B\\)</span> s <span class=\"arithmatex\">\\(|A|=|B|=h\\)</span>.</p>\n<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span> se sudým počtem vrcholů a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje bisekce, která přeřízne <strong>aspoň</strong> <span class=\"arithmatex\">\\(k\\)</span> hran?</p>","u":"@R/ch-zoo/ch-zoo-ulohy-navic.html#un-9-7"},"pojem-min-bisection":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Min Bisection}\\)</span>","b":"<p><em>Bisekce</em> grafu s <span class=\"arithmatex\">\\(2h\\)</span> vrcholy je rozdělení <span class=\"arithmatex\">\\(V=A\\cup B\\)</span> s <span class=\"arithmatex\">\\(|A|=|B|=h\\)</span>.</p>\n<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span> se sudým počtem vrcholů a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje bisekce, která přeřízne <strong>nejvýše</strong> <span class=\"arithmatex\">\\(k\\)</span> hran?</p>","u":"@R/ch-zoo/ch-zoo-ulohy-navic.html#un-9-7"},"pojem-max-2-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{MAX-2-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v CNF, jejíž každá klauzule obsahuje nejvýše dva literály, a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení proměnných, které splní alespoň <span class=\"arithmatex\">\\(k\\)</span> klauzulí formule <span class=\"arithmatex\">\\(\\varphi\\)</span>?</p>","u":"@R/ch-zoo/sec-cv4.html#cv-4-4"},"pojem-max-3-cut":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Max 3-Cut}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> lze <span class=\"arithmatex\">\\(V\\)</span> rozdělit na tři disjunktní části (některá smí být prázdná) tak, aby aspoň <span class=\"arithmatex\">\\(k\\)</span> hran mělo konce v různých částech?</p>","u":"@R/ch-zoo/ch-zoo-ulohy-navic.html#un-9-1"},"pojem-prideleni-kanalu":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Přidělení kanálů}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> (vysílače a dvojice, které se mohou rušit) a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> lze každému vrcholu přidělit kanál <span class=\"arithmatex\">\\(f(v)\\in\\{1,\\dots,k\\}\\)</span> tak, aby <span class=\"arithmatex\">\\(|f(u)-f(v)|\\ge2\\)</span> pro každou hranu <span class=\"arithmatex\">\\(\\{u,v\\}\\)</span>?</p>","u":"@R/ch-zoo/ch-zoo-ulohy-navic.html#un-9-2"},"pojem-exact-cut":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Exact Cut}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje rozdělení <span class=\"arithmatex\">\\(V=A\\cup B\\)</span>, které přeřízne <strong>přesně</strong> <span class=\"arithmatex\">\\(k\\)</span> hran?</p>","u":"@R/ch-zoo/ch-zoo-ulohy-navic.html#un-9-3"},"pojem-pozitivni-1in3":{"t":"Problém pozitivní (monotónní) <span class=\"arithmatex\">\\(\\prob{1-in-3 SAT}\\)</span>","b":"<p><span class=\"arithmatex\">\\(\\prob{1-in-3 SAT}\\)</span> bez negací: všechny literály jsou kladné.</p>\n<p><strong>Vstup:</strong> formule v 3-CNF bez negací.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, při kterém je v každé klauzuli <strong>přesně jeden</strong> literál pravdivý?</p>","u":"@R/ch-x3c/ch-x3c-1-in-3-sat.html#prob-1in3"},"pojem-exact-cover":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Exact Cover}\\)</span>","b":"<p><strong>Vstup:</strong> univerzum <span class=\"arithmatex\">\\(U\\)</span> a systém <span class=\"arithmatex\">\\(\\mathcal S\\)</span> jeho podmnožin <strong>libovolných</strong> velikostí.</p>\n<p><strong>Otázka:</strong> lze vybrat podsystém, který pokryje každý prvek <span class=\"arithmatex\">\\(U\\)</span> právě jednou?</p>","u":"@R/ch-x3c/ch-x3c-ulohy-navic.html#un-10-3"},"pojem-exact-hitting-set":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Exact Hitting Set}\\)</span> (EHS)","b":"<p><strong>Vstup:</strong> konečná množina <span class=\"arithmatex\">\\(A\\)</span> a systém jejích podmnožin <span class=\"arithmatex\">\\(B_1,\\dots,B_r\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(H\\subseteq A\\)</span> taková, že <span class=\"arithmatex\">\\(|H\\cap B_j|=1\\)</span> pro všechna <span class=\"arithmatex\">\\(j\\)</span> (každou množinu zasáhne\npřesně jednou)?</p>","u":"@R/ch-x3c/ch-x3c-ulohy-navic.html#un-10-4"},"pojem-01-soustava":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{0/1 soustava rovnic}\\)</span>","b":"<p><strong>Vstup:</strong> celočíselná matice <span class=\"arithmatex\">\\(A\\)</span> typu <span class=\"arithmatex\">\\(r\\times n\\)</span> a vektor <span class=\"arithmatex\">\\(b\\in\\mathbb Z^r\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(y\\in\\{0,1\\}^n\\)</span> s <span class=\"arithmatex\">\\(Ay=b\\)</span>?</p>","u":"@R/ch-x3c/ch-x3c-ulohy-navic.html#un-10-6"},"pojem-x4c":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{X4C}\\)</span>","b":"<p><strong>Vstup:</strong> univerzum <span class=\"arithmatex\">\\(U\\)</span> s <span class=\"arithmatex\">\\(|U|=4q\\)</span> a systém <span class=\"arithmatex\">\\(\\mathcal S\\)</span> <strong>čtyřprvkových</strong> podmnožin <span class=\"arithmatex\">\\(U\\)</span>.</p>\n<p><strong>Otázka:</strong> lze vybrat <span class=\"arithmatex\">\\(q\\)</span> množin tak, aby byl každý prvek pokryt právě jednou?</p>","u":"@R/ch-x3c/ch-x3c-ulohy-navic.html#un-10-7"},"pojem-2-in-4-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{2-in-4 SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule v CNF, v níž má každá klauzule přesně čtyři literály.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, při kterém jsou v každé klauzuli pravdivé <strong>právě dva</strong> literály?</p>","u":"@R/ch-x3c/ch-x3c-ulohy-navic.html#un-10-2"},"pojem-partition-into-triangles":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Partition into Triangles}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> s <span class=\"arithmatex\">\\(|V|=3q\\)</span>.</p>\n<p><strong>Otázka:</strong> lze <span class=\"arithmatex\">\\(V\\)</span> rozdělit na <span class=\"arithmatex\">\\(q\\)</span> disjunktních trojic tak, aby každá trojice tvořila v <span class=\"arithmatex\">\\(G\\)</span> trojúhelník?</p>","u":"@R/ch-x3c/ch-x3c-ulohy-navic.html#un-10-8"},"pojem-uhp":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{UHP}\\)</span> (neorientovaná hamiltonovská cesta)","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G\\)</span> a vrcholy <span class=\"arithmatex\">\\(S,T\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> cesta z <span class=\"arithmatex\">\\(S\\)</span> do <span class=\"arithmatex\">\\(T\\)</span>, která navštíví každý vrchol právě jednou?</p>","u":"@R/ch-cisla/ch-cisla-hamiltonovska-cesta.html#ch-cisla-dhp-uhp"},"pojem-hc":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{HC}\\)</span> (hamiltonovská kružnice)","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span>.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(G\\)</span> hamiltonovskou kružnici – kružnici, která projde každým vrcholem právě jednou?\n(Pro grafy s méně než 3 vrcholy je odpověď <span class=\"arithmatex\">\\(\\NE\\)</span>.)</p>\n<p>Skripta ho používají hlavně pro neorientované grafy (redukce <span class=\"arithmatex\">\\(\\prob{HC}\\redp\\prob{TSP}\\)</span>, úloha 11.3);\nv redukci <span class=\"arithmatex\">\\(\\prob{DHP}\\redp\\prob{HC}\\)</span> a ve cvičení 7.2 (<span class=\"arithmatex\">\\(\\prob{Hamiltonian Cycle}\\)</span>) jde o orientovaný graf\na orientovanou kružnici.</p>","u":"@R/ch-cisla/ch-cisla-hamiltonovska-cesta.html#ch-cisla-dhp-hc"},"pojem-hp":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{HP}\\)</span> (hamiltonovská cesta)","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G\\)</span>.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(G\\)</span> hamiltonovskou cestu – cestu, která navštíví každý vrchol právě jednou (konce jsou\nlibovolné)?</p>\n<p>Ve cvičení 7.2 (<span class=\"arithmatex\">\\(\\prob{Hamiltonian Path}\\)</span>) jde o orientovaný graf a orientovanou cestu; verze s pevnými\nkonci <span class=\"arithmatex\">\\(S,T\\)</span> je <span class=\"arithmatex\">\\(\\prob{UHP}\\)</span>, resp. orientovaná <span class=\"arithmatex\">\\(\\prob{DHP}\\)</span>.</p>","u":"@R/ch-cisla/ch-cisla-ulohy-navic.html#un-11-3"},"pojem-zero-subset-sum":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Zero Subset Sum}\\)</span>","b":"<p><strong>Vstup:</strong> celá čísla <span class=\"arithmatex\">\\(b_1,\\dots,b_n\\)</span> (mohou být záporná; zapsaná binárně se znaménkem).</p>\n<p><strong>Otázka:</strong> existuje <strong>neprázdná</strong> množina <span class=\"arithmatex\">\\(J\\subseteq\\{1,\\dots,n\\}\\)</span> se <span class=\"arithmatex\">\\(\\sum_{i\\in J}b_i=0\\)</span>?</p>","u":"@R/ch-cisla/ch-cisla-ulohy-navic.html#un-11-4"},"pojem-3way-partition":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{3-Way Partition}\\)</span> (tři loupežníci)","b":"<p><strong>Vstup:</strong> kladná celá čísla <span class=\"arithmatex\">\\(a_1,\\dots,a_n\\)</span>.</p>\n<p><strong>Otázka:</strong> lze je rozdělit do <strong>tří</strong> skupin se stejným součtem?</p>","u":"@R/ch-cisla/ch-cisla-ulohy-navic.html#un-11-5"},"pojem-rozvrh-s-okny":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Rozvrh s okny}\\)</span>","b":"<p><strong>Vstup:</strong> <span class=\"arithmatex\">\\(n\\)</span> úloh; úloha <span class=\"arithmatex\">\\(j\\)</span> má délku <span class=\"arithmatex\">\\(p_j\\ge1\\)</span>, čas uvolnění <span class=\"arithmatex\">\\(r_j\\)</span> a termín <span class=\"arithmatex\">\\(d_j\\)</span> (čísla zapsaná binárně).</p>\n<p><strong>Otázka:</strong> lze úlohy rozvrhnout bez přerušení na <strong>jeden</strong> stroj, tj. zvolit začátky <span class=\"arithmatex\">\\(\\sigma_j\\)</span> s <span class=\"arithmatex\">\\(r_j\\le\\sigma_j\\)</span> a <span class=\"arithmatex\">\\(\\sigma_j+p_j\\le d_j\\)</span> tak, aby se žádné dva intervaly <span class=\"arithmatex\">\\([\\sigma_j,\\sigma_j+p_j)\\)</span> nepřekrývaly?</p>","u":"@R/ch-cisla/ch-cisla-ulohy-navic.html#un-11-8"},"pojem-unsat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{UNSAT}\\)</span>","b":"<p><strong>Vstup:</strong> booleovská formule <span class=\"arithmatex\">\\(\\varphi\\)</span>.</p>\n<p><strong>Otázka:</strong> je <span class=\"arithmatex\">\\(\\varphi\\)</span> nesplnitelná?</p>\n<p>Leží v <span class=\"arithmatex\">\\(\\coNP\\)</span>. Pozor: <span class=\"arithmatex\">\\(\\overline{\\prob{SAT}}\\neq\\prob{UNSAT}\\)</span> – doplněk obsahuje i vstupy, které nejsou formulí.</p>","u":"@R/ch-prostor/ch-prostor-doplnky-jazyku-conp-a-conl.html#def-conp"},"pojem-taut":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{TAUT}\\)</span>","b":"<p><strong>Vstup:</strong> booleovská formule <span class=\"arithmatex\">\\(\\varphi\\)</span>.</p>\n<p><strong>Otázka:</strong> je <span class=\"arithmatex\">\\(\\varphi\\)</span> tautologie (pravdivá při každém ohodnocení)?</p>\n<p>Leží v <span class=\"arithmatex\">\\(\\coNP\\)</span>; platí <span class=\"arithmatex\">\\(\\varphi\\in\\prob{TAUT}\\iff\\lnot\\varphi\\in\\prob{UNSAT}\\)</span>.</p>","u":"@R/ch-prostor/ch-prostor-doplnky-jazyku-conp-a-conl.html#def-conp"},"pojem-2sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{2-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> formule v 2-CNF, tj. v CNF, kde má každá klauzule <strong>nejvýš dva</strong> literály.</p>\n<p><strong>Otázka:</strong> je formule splnitelná?</p>\n<p>Na rozdíl od <span class=\"arithmatex\">\\(\\prob{3-SAT}\\)</span> je v <span class=\"arithmatex\">\\(\\PP\\)</span> (implikační graf a silně souvislé komponenty), dokonce v <span class=\"arithmatex\">\\(\\NL\\)</span>.</p>","u":"@R/ch-prostor/ch-prostor-2-sat-je-v-p.html#thm-2sat"},"pojem-misere-gg":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Misère GG}\\)</span> (geografie naruby)","b":"<p>Pravidla jako <span class=\"arithmatex\">\\(\\prob{Generalized Geography}\\)</span>, ale hráč, který nemůže táhnout, <strong>vyhrál</strong>.</p>\n<p><strong>Otázka:</strong> má Alice vítěznou strategii?</p>","u":"@R/ch-pspace/ch-pspace-ulohy-navic.html#un-13-8"},"pojem-horn-sat":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Horn-SAT}\\)</span>","b":"<p><strong>Vstup:</strong> Hornova formule – CNF, v níž každá klauzule obsahuje <strong>nejvýše jeden kladný</strong> literál.</p>\n<p><strong>Otázka:</strong> je formule splnitelná?</p>\n<p>Rozhodne se v polynomiálním čase jediným hladovým průchodem (unit propagation).</p>","u":"@R/ch-resice-sat/ch-resice-sat-snadne-varianty-satu.html#ch-resice-sat-horn-sat"},"pojem-queens-completion":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Queens Completion}\\)</span> (doplnění dam)","b":"<p><strong>Vstup:</strong> šachovnice <span class=\"arithmatex\">\\(n\\times n\\)</span> a množina políček <span class=\"arithmatex\">\\(P\\)</span>, na kterých už stojí dámy.</p>\n<p><strong>Otázka:</strong> lze přidat další dámy tak, aby jich na šachovnici bylo celkem <span class=\"arithmatex\">\\(n\\)</span> a žádné dvě se neohrožovaly\n(nestály ve stejném řádku, sloupci ani na stejné diagonále)?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-5"},"pojem-coloring":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Coloring}\\)</span> (<span class=\"arithmatex\">\\(k\\)</span>-barevnost)","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a počet barev <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> lze vrcholy <span class=\"arithmatex\">\\(G\\)</span> obarvit <span class=\"arithmatex\">\\(k\\)</span> barvami tak, aby sousedé měli různé barvy?</p>\n<p>Pro pevné <span class=\"arithmatex\">\\(k\\)</span> (není součástí vstupu) se píše <span class=\"arithmatex\">\\(k\\text{-}\\prob{Coloring}\\)</span>; pro <span class=\"arithmatex\">\\(k\\ge3\\)</span> je NP-úplný.</p>","u":"@R/ch-resice-sat/ch-resice-sat-redukce-do-sat.html#ch-resice-sat-k-barevnost"},"pojem-latin-square-completion":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Latin Square Completion}\\)</span> (doplnění latinského čtverce)","b":"<p><strong>Vstup:</strong> číslo <span class=\"arithmatex\">\\(n\\)</span> a částečně vyplněná tabulka <span class=\"arithmatex\">\\(n\\times n\\)</span>, tj. množina <span class=\"arithmatex\">\\(P\\)</span> trojic <span class=\"arithmatex\">\\((r,s,v)\\)</span> „na políčku <span class=\"arithmatex\">\\((r,s)\\)</span> je číslo <span class=\"arithmatex\">\\(v\\)</span>“.</p>\n<p><strong>Otázka:</strong> lze tabulku doplnit na latinský čtverec (v každém řádku i sloupci je každé z čísel <span class=\"arithmatex\">\\(1,\\dots,n\\)</span> právě jednou)?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-1"},"pojem-instalace-balicku":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Instalace balíčků}\\)</span>","b":"<p><strong>Vstup:</strong> množina balíčků <span class=\"arithmatex\">\\(B\\)</span>, skupiny verzí <span class=\"arithmatex\">\\(V_1,\\dots,V_q\\subseteq B\\)</span>, závislosti <span class=\"arithmatex\">\\((p,D)\\)</span> s <span class=\"arithmatex\">\\(p\\in B\\)</span>, <span class=\"arithmatex\">\\(D\\subseteq B\\)</span>, konfliktní dvojice <span class=\"arithmatex\">\\(K\\)</span> a cílová množina <span class=\"arithmatex\">\\(T\\subseteq B\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje instalace <span class=\"arithmatex\">\\(I\\subseteq B\\)</span>, <span class=\"arithmatex\">\\(T\\subseteq I\\)</span>, v níž je z každé skupiny <span class=\"arithmatex\">\\(V_i\\)</span> nejvýše jeden balíček, s každým <span class=\"arithmatex\">\\(p\\in I\\)</span> i aspoň jeden balíček z každé jeho závislosti <span class=\"arithmatex\">\\(D\\)</span> a žádná konfliktní dvojice?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-2"},"pojem-minesweeper":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Minesweeper}\\)</span> (hledání min, konzistence)","b":"<p><strong>Vstup:</strong> mřížka <span class=\"arithmatex\">\\(R\\times S\\)</span>, v níž jsou některá políčka odkrytá (bez miny) a nesou číslo <span class=\"arithmatex\">\\(c(p)\\in\\{0,\\dots,8\\}\\)</span>.</p>\n<p><strong>Otázka:</strong> lze do zakrytých políček rozmístit miny tak, aby každé číslo <span class=\"arithmatex\">\\(c(p)\\)</span> bylo rovno počtu min mezi (až osmi) sousedy políčka <span class=\"arithmatex\">\\(p\\)</span>?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-3"},"pojem-rozsazeni-hostu":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Rozsazení hostů}\\)</span>","b":"<p><strong>Vstup:</strong> hosté <span class=\"arithmatex\">\\(H\\)</span>, <span class=\"arithmatex\">\\(|H|=n\\)</span>, <span class=\"arithmatex\">\\(k\\)</span> stolů po <span class=\"arithmatex\">\\(c\\)</span> místech, dvojice nepřátel <span class=\"arithmatex\">\\(N\\)</span>, páry <span class=\"arithmatex\">\\(P\\)</span> a pro každého hosta <span class=\"arithmatex\">\\(g\\)</span> množina kamarádů <span class=\"arithmatex\">\\(F(g)\\)</span>.</p>\n<p><strong>Otázka:</strong> lze každého hosta posadit k jednomu stolu tak, aby u stolu bylo nejvýše <span class=\"arithmatex\">\\(c\\)</span> hostů, nepřátelé neseděli spolu, páry seděly spolu a každý měl u stolu aspoň jednoho kamaráda?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-4"},"pojem-rozvrh-se-zavislostmi":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Rozvrh se závislostmi}\\)</span>","b":"<p><strong>Vstup:</strong> úlohy <span class=\"arithmatex\">\\(J\\)</span> délky <span class=\"arithmatex\">\\(1\\)</span>, počet procesorů <span class=\"arithmatex\">\\(m\\)</span>, počet kroků <span class=\"arithmatex\">\\(T\\)</span>, pro každou úlohu okno <span class=\"arithmatex\">\\(r_j\\le d_j\\)</span> a závislosti <span class=\"arithmatex\">\\(Z\\subseteq J\\times J\\)</span>.</p>\n<p><strong>Otázka:</strong> lze každé úloze <span class=\"arithmatex\">\\(j\\)</span> přidělit krok <span class=\"arithmatex\">\\(\\sigma(j)\\in[r_j,d_j]\\)</span> tak, aby v žádném kroku neběželo víc než <span class=\"arithmatex\">\\(m\\)</span> úloh a pro <span class=\"arithmatex\">\\((i,j)\\in Z\\)</span> platilo <span class=\"arithmatex\">\\(\\sigma(i)&lt;\\sigma(j)\\)</span>?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-6"},"pojem-zhasni-svetla":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Zhasni světla}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span>, množina rozsvícených vrcholů <span class=\"arithmatex\">\\(L\\subseteq V\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>; stisk vrcholu <span class=\"arithmatex\">\\(v\\)</span> přepne světla v uzavřeném okolí <span class=\"arithmatex\">\\(N[v]\\)</span>.</p>\n<p><strong>Otázka:</strong> lze nejvýše <span class=\"arithmatex\">\\(k\\)</span> stisky zhasnout všechna světla?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-7"},"pojem-prevoznik":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Převozník}\\)</span>","b":"<p><strong>Vstup:</strong> předměty <span class=\"arithmatex\">\\(V\\)</span> na levém břehu, kapacita loďky <span class=\"arithmatex\">\\(c\\)</span>, konfliktní dvojice <span class=\"arithmatex\">\\(K\\)</span> (nesmějí zůstat na břehu bez převozníka) a počet kroků <span class=\"arithmatex\">\\(T\\)</span> zadaný unárně.</p>\n<p><strong>Otázka:</strong> lze všechny předměty dostat na pravý břeh nejvýše za <span class=\"arithmatex\">\\(T\\)</span> kroků (krok = převozník přepluje s nejvýše <span class=\"arithmatex\">\\(c\\)</span> předměty, nebo stojí)?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-8"},"pojem-pfp":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Path with Forbidden Pairs}\\)</span> (PFP)","b":"<p><strong>Vstup:</strong> orientovaný graf <span class=\"arithmatex\">\\(G=(V,A)\\)</span>, vrcholy <span class=\"arithmatex\">\\(s,t\\in V\\)</span> a množina zakázaných dvojic <span class=\"arithmatex\">\\(P\\subseteq\\binom V2\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> orientovaná cesta (bez opakování vrcholů) z <span class=\"arithmatex\">\\(s\\)</span> do <span class=\"arithmatex\">\\(t\\)</span>, která z žádné dvojice\n<span class=\"arithmatex\">\\(\\{u,v\\}\\in P\\)</span> neobsahuje oba vrcholy?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-1"},"pojem-deg3-spanning-tree":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Deg-3 Spanning Tree}\\)</span>","b":"<p><strong>Vstup:</strong> souvislý neorientovaný graf <span class=\"arithmatex\">\\(G\\)</span>.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(G\\)</span> kostru (podgraf, který je stromem a obsahuje všechny vrcholy), v níž má každý vrchol\nstupeň nejvýše 3?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-2"},"pojem-fas":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Feedback Arc Set}\\)</span> (FAS)","b":"<p><strong>Vstup:</strong> orientovaný graf <span class=\"arithmatex\">\\(G=(V,A)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje množina hran <span class=\"arithmatex\">\\(F\\subseteq A\\)</span>, <span class=\"arithmatex\">\\(|F|\\le k\\)</span>, taková, že graf <span class=\"arithmatex\">\\((V,A\\setminus F)\\)</span> neobsahuje\nžádný orientovaný cyklus?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-4"},"pojem-ridka-mnozina":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Řídká množina}\\)</span> (dissociation set)","b":"<p>Množina <span class=\"arithmatex\">\\(S\\subseteq V\\)</span> je <em>řídká</em>, pokud každý vrchol z <span class=\"arithmatex\">\\(S\\)</span> má v <span class=\"arithmatex\">\\(S\\)</span> nejvýše jednoho souseda.</p>\n<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> řídká množina <span class=\"arithmatex\">\\(S\\)</span> s <span class=\"arithmatex\">\\(|S|\\ge k\\)</span>?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-5"},"pojem-odebrani-na-stupen-2":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Odebrání na stupeň 2}\\)</span>","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(S\\subseteq V\\)</span>, <span class=\"arithmatex\">\\(|S|\\le k\\)</span>, takové, že v <span class=\"arithmatex\">\\(G-S\\)</span> má každý vrchol stupeň nejvýše 2?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-8"},"pojem-rozbiti-trojuhelniku":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Rozbití trojúhelníků}\\)</span>","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(S\\subseteq V\\)</span>, <span class=\"arithmatex\">\\(|S|\\le k\\)</span>, takové, že graf <span class=\"arithmatex\">\\(G-S\\)</span> neobsahuje žádný trojúhelník?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-9"},"pojem-cvc":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Connected Vertex Cover}\\)</span> (souvislé vrcholové pokrytí)","b":"<p><strong>Vstup:</strong> souvislý graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje vrcholové pokrytí <span class=\"arithmatex\">\\(C\\subseteq V\\)</span>, <span class=\"arithmatex\">\\(|C|\\le k\\)</span>, takové, že podgraf <span class=\"arithmatex\">\\(G[C]\\)</span> je souvislý?</p>","u":"@R/ch-typove/ch-typove-typ-2-self-redukce.html#typ-2-9"},"pojem-podposloupnost":{"t":"Podposloupnost (vybrané podslovo)","b":"<p>Slovo <span class=\"arithmatex\">\\(x\\)</span> je <em>podposloupnost</em> slova <span class=\"arithmatex\">\\(y\\)</span>, když vznikne z <span class=\"arithmatex\">\\(y\\)</span> vynecháním některých symbolů:\n<span class=\"arithmatex\">\\(x=y_{j_1}y_{j_2}\\cdots y_{j_k}\\)</span> pro nějaké indexy <span class=\"arithmatex\">\\(j_1&lt;j_2&lt;\\dots&lt;j_k\\)</span>. Na rozdíl od souvislého podslova\nnemusí vybrané symboly ležet vedle sebe.</p>","u":"@R/ch-typove/ch-typove-typ-1-turinguv-stroj.html#typ-1-7"},"pojem-cyklicky-posun":{"t":"Cyklický posun","b":"<p>Slovo <span class=\"arithmatex\">\\(x\\)</span> je <em>cyklický posun</em> slova <span class=\"arithmatex\">\\(y\\)</span>, když <span class=\"arithmatex\">\\(y=uv\\)</span> a <span class=\"arithmatex\">\\(x=vu\\)</span> pro nějaká slova <span class=\"arithmatex\">\\(u,v\\)</span>. Ekvivalentně\n<span class=\"arithmatex\">\\(|x|=|y|\\)</span> a <span class=\"arithmatex\">\\(x\\)</span> je souvislé podslovo slova <span class=\"arithmatex\">\\(yy\\)</span>.</p>","u":"@R/ch-typove/ch-typove-typ-1-turinguv-stroj.html#typ-1-8"},"pojem-spolecne-slovo":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Společné slovo}\\)</span>","b":"<p><strong>Vstup:</strong> <span class=\"arithmatex\">\\(m\\)</span> deterministických konečných automatů <span class=\"arithmatex\">\\(A_1,\\dots,A_m\\)</span> nad abecedou <span class=\"arithmatex\">\\(\\{0,1\\}\\)</span> a číslo <span class=\"arithmatex\">\\(n\\)</span>\nzapsané unárně (<span class=\"arithmatex\">\\(1^n\\)</span>).</p>\n<p><strong>Otázka:</strong> existuje slovo <span class=\"arithmatex\">\\(w\\in\\{0,1\\}^n\\)</span> (délky přesně <span class=\"arithmatex\">\\(n\\)</span>), které přijímají všechny automaty?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-6"},"pojem-vyvazene-rozdeleni":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Vyvážené rozdělení}\\)</span>","b":"<p><strong>Vstup:</strong> <span class=\"arithmatex\">\\(2N\\)</span> kladných celých čísel <span class=\"arithmatex\">\\(b_1,\\dots,b_{2N}\\)</span> (binárně).</p>\n<p><strong>Otázka:</strong> lze čísla rozdělit na dvě skupiny <strong>po <span class=\"arithmatex\">\\(N\\)</span> číslech</strong> se stejným součtem?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-7"},"pojem-jadro":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Jádro}\\)</span>","b":"<p>Množina <span class=\"arithmatex\">\\(K\\subseteq V\\)</span> orientovaného grafu <span class=\"arithmatex\">\\(G=(V,A)\\)</span> je <em>jádro</em>, je-li <strong>nezávislá</strong> (mezi žádnými dvěma\nvrcholy <span class=\"arithmatex\">\\(K\\)</span> nevede hrana) a <strong>absorbující</strong> (z každého <span class=\"arithmatex\">\\(v\\notin K\\)</span> vede hrana do nějakého vrcholu <span class=\"arithmatex\">\\(K\\)</span>).</p>\n<p><strong>Vstup:</strong> orientovaný graf <span class=\"arithmatex\">\\(G\\)</span>.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(G\\)</span> jádro?</p>","u":"@R/ch-ukazkovy/ch-ukazkovy-uloha-4-np-uplnost.html#ut-4"},"pojem-graph-isomorphism":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Graph Isomorphism}\\)</span> (izomorfismus grafů)","b":"<p><strong>Vstup:</strong> grafy <span class=\"arithmatex\">\\(G\\)</span> a <span class=\"arithmatex\">\\(H\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje bijekce <span class=\"arithmatex\">\\(\\psi\\colon V(G)\\to V(H)\\)</span>, pro kterou <span class=\"arithmatex\">\\(uv\\in E(G)\\iff\\psi(u)\\psi(v)\\in E(H)\\)</span>?</p>\n<p>Je v <span class=\"arithmatex\">\\(\\NP\\)</span>, ale neví se, zda je NP-úplný.</p>","u":"@R/ch-np/ch-np-ulohy-navic.html#un-4-9"},"pojem-3sat-3k":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{3-SAT-3K}\\)</span>","b":"<p><strong>Vstup:</strong> formule v CNF, kde má každá klauzule nejvýše tři literály a každá proměnná leží nejvýše ve\n<strong>třech klauzulích</strong>.</p>\n<p><strong>Otázka:</strong> je formule splnitelná?</p>\n<p>Na rozdíl od <span class=\"arithmatex\">\\(\\prob{3-SAT-3}\\)</span> (úloha 7.6) se nepočítají výskyty, ale klauzule.</p>","u":"@R/ch-sat/ch-sat-ulohy-navic.html#un-7-11"},"pojem-3dm":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{3DM}\\)</span> (trojrozměrné párování)","b":"<p><strong>Vstup:</strong> disjunktní množiny <span class=\"arithmatex\">\\(X,Y,Z\\)</span>, každá s <span class=\"arithmatex\">\\(q\\)</span> prvky, a množina trojic <span class=\"arithmatex\">\\(T\\subseteq X\\times Y\\times Z\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(M\\subseteq T\\)</span> taková, že každý prvek <span class=\"arithmatex\">\\(X\\cup Y\\cup Z\\)</span> leží v právě jedné trojici z <span class=\"arithmatex\">\\(M\\)</span>\n(pak <span class=\"arithmatex\">\\(|M|=q\\)</span>)?</p>\n<p>Je to zvláštní případ <span class=\"arithmatex\">\\(\\prob{X3C}\\)</span>.</p>","u":"@R/ch-x3c/ch-x3c-ulohy-navic.html#un-10-10"},"pojem-01-ilp":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{0-1 ILP}\\)</span> (0/1 celočíselná přípustnost)","b":"<p><strong>Vstup:</strong> celočíselná matice <span class=\"arithmatex\">\\(A\\)</span> typu <span class=\"arithmatex\">\\(p\\times n\\)</span> a celočíselný vektor <span class=\"arithmatex\">\\(b\\)</span>.</p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(x\\in\\{0,1\\}^n\\)</span> s <span class=\"arithmatex\">\\(Ax\\ge b\\)</span>?</p>","u":"@R/ch-cisla/ch-cisla-ulohy-navic.html#un-11-12"},"pojem-multiprocessor-scheduling":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Multiprocessor Scheduling}\\)</span> (rozvrh na <span class=\"arithmatex\">\\(m\\)</span> strojů)","b":"<p><strong>Vstup:</strong> délky úloh <span class=\"arithmatex\">\\(p_1,\\dots,p_n\\)</span>, počet strojů <span class=\"arithmatex\">\\(m\\)</span> a termín <span class=\"arithmatex\">\\(D\\)</span>.</p>\n<p><strong>Otázka:</strong> lze úlohy rozdělit na <span class=\"arithmatex\">\\(m\\)</span> stejných strojů tak, aby součet délek na každém stroji byl nejvýše <span class=\"arithmatex\">\\(D\\)</span>?</p>","u":"@R/ch-cisla/ch-cisla-ulohy-navic.html#un-11-15"},"pojem-rozvrh-dva-stroje":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Rozvrh na dva stroje}\\)</span>","b":"<p><strong>Vstup:</strong> délky úloh <span class=\"arithmatex\">\\(p_1,\\dots,p_n\\in\\N\\)</span> (zapsané binárně) a termín <span class=\"arithmatex\">\\(D\\in\\N\\)</span>.</p>\n<p><strong>Otázka:</strong> lze úlohy rozdělit na dva stejné stroje tak, aby součet délek úloh na každém stroji byl nejvýše <span class=\"arithmatex\">\\(D\\)</span>?</p>","u":"@R/ch-typove/ch-typove-typ-4-np-tezkost.html#typ-4-3"},"pojem-bounded-degree-spanning-tree":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Bounded-Degree Spanning Tree}\\)</span> (kostra s omezeným stupněm)","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span> a číslo <span class=\"arithmatex\">\\(k\\ge1\\)</span>.</p>\n<p><strong>Otázka:</strong> má <span class=\"arithmatex\">\\(G\\)</span> kostru, v níž má každý vrchol stupeň nejvýše <span class=\"arithmatex\">\\(k\\)</span>?</p>","u":"@R/ch-cisla/ch-cisla-ulohy-navic.html#un-11-16"},"pojem-long-cycle":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Long Cycle}\\)</span> (dlouhá kružnice)","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G\\)</span> a přirozené číslo <span class=\"arithmatex\">\\(k\\)</span>.</p>\n<p><strong>Otázka:</strong> obsahuje <span class=\"arithmatex\">\\(G\\)</span> kružnici (bez opakování vrcholů) s aspoň <span class=\"arithmatex\">\\(k\\)</span> hranami?</p>","u":"@R/ch-resice-sat/ch-resice-sat-ulohy-navic.html#un-14-12"},"pojem-edge-cover":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Edge Cover}\\)</span> (hranové pokrytí)","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span>.</p>\n<p><strong>Úkol:</strong> najít nejmenší <span class=\"arithmatex\">\\(F\\subseteq E\\)</span> takovou, že každý vrchol je koncem aspoň jedné hrany z <span class=\"arithmatex\">\\(F\\)</span>\n(existuje, právě když <span class=\"arithmatex\">\\(G\\)</span> nemá izolovaný vrchol).</p>","u":"@R/ch-resice-ilp/ch-resice-ilp-ulohy-navic.html#un-15-13"},"pojem-max-matching":{"t":"Problém <span class=\"arithmatex\">\\(\\prob{Max Matching}\\)</span> (největší párování)","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span>.</p>\n<p><strong>Úkol:</strong> najít největší párování – množinu hran, z nichž žádné dvě nemají společný vrchol.</p>","u":"@R/ch-resice-ilp/ch-resice-ilp-ulohy-navic.html#un-15-14"},"def-bigo":{"t":"Definice 3.4: Velké <span class=\"arithmatex\">\\(O\\)</span>","b":"<p>Pro funkce <span class=\"arithmatex\">\\(f(n)\\ge1\\)</span> a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(g(n)\\ge 1\\)</span>:</span></p>\n<div class=\"arithmatex\">\\[f(n)=O(g(n)) \\iff \\exists c\\in\\N\\ \\ \\forall n\\in\\N:\\ f(n)\\le c\\cdot g(n).\\]</div>\n<p>Formálně je <span class=\"arithmatex\">\\(O(g(n))\\)</span> množina funkcí, takže bychom měli psát <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f\\in O(g)\\)</span>,</span> ale v informatice je hluboce zakořeněná konvence psát rovnítko.</p>","u":"@R/ch-cas/ch-cas-asymptoticka-notace.html#def-bigo"},"def-konstr":{"t":"Definice 3.6: Časová konstruovatelnost","b":"<p>Funkce <span class=\"arithmatex\">\\(f\\colon\\N\\to\\N\\)</span> je <strong>časově konstruovatelná</strong>, pokud existuje TS, který na vstupu <span class=\"arithmatex\">\\(1^n\\)</span> spočítá <span class=\"arithmatex\">\\(f(n)\\)</span> v čase <span class=\"arithmatex\">\\(c\\cdot f(n)\\)</span> pro nějakou konstantu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(c\\in\\N\\)</span>.</span></p>","u":"@R/ch-cas/ch-cas-deterministicka-casova-hierarchie.html#def-konstr"},"thm-hierarchie":{"t":"Věta 3.7 (O časové hierarchii)","b":"<p>Nechť <span class=\"arithmatex\">\\(f,g\\)</span> jsou časově konstruovatelné a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f(n)\\cdot\\log f(n) = o(g(n))\\)</span>.</span> Pak</p>\n<div class=\"arithmatex\">\\[\\DTIME(f(n)) \\subsetneq \\DTIME(g(n)).\\]</div>\n<p>(Logaritmus je přesně cena simulace na univerzálním stroji, viz důsledek <a href=\"@R/ch-ts/ch-ts-univerzalni-turinguv-stroj.html#cor-uts\">1.9</a>.)</p>","u":"@R/ch-cas/ch-cas-deterministicka-casova-hierarchie.html#thm-hierarchie"},"cor-pexp":{"t":"Důsledek 3.8: <span class=\"arithmatex\">\\(\\PP\\subsetneq\\EXP\\)</span>","b":"<p>Pro <span class=\"arithmatex\">\\(f(n)=n^d\\)</span> a <span class=\"arithmatex\">\\(g(n)=2^{n^{d+1}}\\)</span> dostaneme <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\DTIME(n^d)\\subsetneq\\DTIME(2^{n^{d+1}})\\)</span>.</span> Sjednocením přes všechna <span class=\"arithmatex\">\\(d\\)</span> plyne <span class=\"arithmatex\">\\(\\PP\\subsetneq\\EXP\\)</span> – jedna z mála <em>bezpodmínečných</em> separací, které umíme dokázat.</p>","u":"@R/ch-cas/ch-cas-deterministicka-casova-hierarchie.html#cor-pexp"},"thm-speedup":{"t":"Věta 3.2 (O lineárním zrychlení)","b":"<p>Pro každé <span class=\"arithmatex\">\\(\\varepsilon&gt;0\\)</span> a každý stroj <span class=\"arithmatex\">\\(M\\)</span> pracující v čase <span class=\"arithmatex\">\\(T_M(n)\\)</span> existuje ekvivalentní stroj <span class=\"arithmatex\">\\(M'\\)</span> pracující v čase</p>\n<div class=\"arithmatex\">\\[T_{M'}(n) \\le n + 3 + \\bigl\\lceil \\varepsilon\\cdot\\bigl(n+T_M(n)\\bigr)\\bigr\\rceil.\\]</div>","u":"@R/ch-cas/ch-cas-linearni-zrychleni.html#thm-speedup"},"cor-nokonst":{"t":"Důsledek 3.3","b":"<p>Nemá smysl řešit multiplikativní konstanty – čas zapisujeme v <span class=\"arithmatex\">\\(O\\)</span>-notaci.</p>","u":"@R/ch-cas/ch-cas-linearni-zrychleni.html#cor-nokonst"},"def-tridy":{"t":"Definice 3.5: Třídy časové složitosti","b":"<ul><li><span class=\"arithmatex\">\\(\\DTIME(f)\\)</span> je třída jazyků rozhodnutelných (deterministickým TS) v čase <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(O(f(n))\\)</span>.</span></li><li><span class=\"arithmatex\">\\(\\displaystyle \\PP = \\bigcup_{d=1}^{\\infty}\\DTIME(n^d) \\quad\\)</span> – deterministický polynomiální čas,</li><li><span class=\"arithmatex\">\\(\\displaystyle \\EXP = \\bigcup_{d=1}^{\\infty}\\DTIME\\bigl(2^{n^d}\\bigr) \\quad\\)</span> – exponenciální čas.</li></ul>","u":"@R/ch-cas/ch-cas-tridy-p-a-exp.html#def-tridy"},"def-casova":{"t":"Definice 3.1: Časová složitost","b":"<p>TS <span class=\"arithmatex\">\\(M\\)</span> pracuje v čase <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(T_M(n)\\)</span>,</span> pokud výpočet <span class=\"arithmatex\">\\(M\\)</span> na <em>libovolném</em> vstupu délky <span class=\"arithmatex\">\\(n\\)</span> skončí po nejvýše <span class=\"arithmatex\">\\(T_M(n)\\)</span> krocích (jde o analýzu nejhoršího případu).</p>","u":"@R/ch-cas/index.html#def-casova"},"prob-subsetsum":{"t":"Problém 11.8: <span class=\"arithmatex\">\\(\\prob{Subset Sum}\\)</span> (součet podmnožiny)","b":"<p><strong>Vstup:</strong> kladná celá čísla <span class=\"arithmatex\">\\(a_1,\\dots,a_n\\)</span> a cíl <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(T\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje <span class=\"arithmatex\">\\(I\\subseteq\\{1,\\dots,n\\}\\)</span> taková, že <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\sum_{i\\in I}a_i=T\\)</span>?</span></p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#prob-subsetsum"},"prob-partition":{"t":"Problém 11.9: <span class=\"arithmatex\">\\(\\prob{Partition}\\)</span> (dva loupežníci)","b":"<p><strong>Vstup:</strong> kladná celá čísla <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(a_1,\\dots,a_n\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze je rozdělit na dvě skupiny se stejným součtem?</p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#prob-partition"},"prob-knapsack":{"t":"Problém 11.11: <span class=\"arithmatex\">\\(\\prob{Knapsack}\\)</span> (problém batohu)","b":"<p><strong>Vstup:</strong> předměty s váhami <span class=\"arithmatex\">\\(w_1,\\dots,w_n\\)</span> a cenami <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(c_1,\\dots,c_n\\)</span>,</span> nosnost <span class=\"arithmatex\">\\(W\\)</span> a cílová cena <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(C\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze vybrat předměty s celkovou váhou <span class=\"arithmatex\">\\(\\le W\\)</span> a celkovou cenou <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\ge C\\)</span>?</span></p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#prob-knapsack"},"thm-ssdp":{"t":"Věta 11.12 (Pseudopolynomiální algoritmus)","b":"<p><span class=\"arithmatex\">\\(\\prob{Subset Sum}\\)</span> lze rozhodnout v čase <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(O(n\\cdot T)\\)</span>.</span></p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#thm-ssdp"},"def-pseudopoly":{"t":"Definice 11.13: Pseudopolynomiální algoritmus","b":"<p>Algoritmus je <em>pseudopolynomiální</em>, pokud je jeho čas polynomiální vůči délce vstupu <em>a velikosti (hodnotě) čísel na vstupu</em> – tedy polynomiální, kdyby byla čísla zapsaná unárně – ale může být exponenciální vůči délce binárního zápisu.</p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#def-pseudopoly"},"def-silne":{"t":"Definice 11.14: Silně a slabě NP-těžký problém","b":"<p>Problém je <em>silně NP-těžký</em>, pokud zůstává NP-těžký, i když jsou všechna čísla na vstupu omezena polynomem ve velikosti vstupu (ekvivalentně: i při <em>unárním</em> zápisu čísel).</p>\n<p>Problém je <em>slabě NP-úplný</em>, je-li NP-úplný, ale má pseudopolynomiální algoritmus.</p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#def-silne"},"prob-3partition":{"t":"Problém 11.15: <span class=\"arithmatex\">\\(\\prob{3-Partition}\\)</span>","b":"<p><strong>Vstup:</strong> <span class=\"arithmatex\">\\(3q\\)</span> kladných celých čísel se součtem <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(qB\\)</span>,</span> každé <em>ostře</em> mezi <span class=\"arithmatex\">\\(B/4\\)</span> a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(B/2\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze čísla rozdělit na <span class=\"arithmatex\">\\(q\\)</span> trojic, z nichž každá má součet přesně <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(B\\)</span>?</span></p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#prob-3partition"},"thm-3partsilne":{"t":"Věta 11.16 (Garey, Johnson 1975)","b":"<p><span class=\"arithmatex\">\\(\\prob{3-Partition}\\)</span> je silně NP-úplný – i s čísly zapsanými unárně. (Bez důkazu.)</p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#thm-3partsilne"},"prob-binpacking":{"t":"Problém 11.17: <span class=\"arithmatex\">\\(\\prob{Bin Packing}\\)</span> (rozhodovací verze)","b":"<p><strong>Vstup:</strong> předměty velikostí <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(s_1,\\dots,s_n\\)</span>,</span> kapacita koše <span class=\"arithmatex\">\\(B\\)</span> a počet košů <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(q\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze všechny předměty rozdělit do <span class=\"arithmatex\">\\(q\\)</span> košů tak, aby žádný nepřetekl?</p>","u":"@R/ch-cisla/ch-cisla-ciselne-problemy.html#prob-binpacking"},"prob-dhp":{"t":"Problém 11.1: <span class=\"arithmatex\">\\(\\prob{Directed Hamiltonian Path}\\)</span> (DHP)","b":"<p><strong>Vstup:</strong> orientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a vrcholy <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(S,T\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> orientovaná cesta z <span class=\"arithmatex\">\\(S\\)</span> do <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(T\\)</span>,</span> která navštíví každý vrchol <em>právě jednou</em>?</p>","u":"@R/ch-cisla/ch-cisla-hamiltonovska-cesta.html#prob-dhp"},"lem-odskok":{"t":"Lemma 11.2: O odskoku","b":"<p>Vstoupí-li hamiltonovská cesta z vrcholu <span class=\"arithmatex\">\\(u\\)</span> do <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(C_j\\)</span>,</span> pak z <span class=\"arithmatex\">\\(C_j\\)</span> pokračuje do <span class=\"arithmatex\">\\(v\\)</span> (druhého vrcholu téhož páru). Symetricky pro odskok <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(v\\to C_j\\to u\\)</span>.</span></p>","u":"@R/ch-cisla/ch-cisla-hamiltonovska-cesta.html#lem-odskok"},"thm-dhpnpc":{"t":"Věta 11.4","b":"<p><span class=\"arithmatex\">\\(\\prob{DHP}\\)</span> je NP-úplný.</p>","u":"@R/ch-cisla/ch-cisla-hamiltonovska-cesta.html#thm-dhpnpc"},"prob-longpath":{"t":"Problém 11.5: <span class=\"arithmatex\">\\(\\prob{Longest Path}\\)</span> (nejdelší cesta)","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> cesta (bez opakování vrcholů) s alespoň <span class=\"arithmatex\">\\(k\\)</span> hranami?</p>","u":"@R/ch-cisla/ch-cisla-hamiltonovska-cesta.html#prob-longpath"},"prob-ilp":{"t":"Problém 11.6: <span class=\"arithmatex\">\\(\\prob{Integer Linear Programming}\\)</span> (ILP)","b":"<p><strong>Proměnné:</strong> <span class=\"arithmatex\">\\(x_1,\\dots,x_n\\in\\mathbb Z\\)</span> (často jen binární, <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\{0,1\\}\\)</span>).</span></p>\n<p><strong>Účelová funkce:</strong> minimalizovat (nebo maximalizovat) <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(c_1x_1+\\dots+c_nx_n\\)</span>.</span></p>\n<p><strong>Omezení:</strong> soustava lineárních nerovnic <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Ax\\le b\\)</span>.</span></p>\n<p><strong>Rozhodovací verze:</strong> existuje celočíselné <span class=\"arithmatex\">\\(x\\)</span> splňující <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Ax\\le b\\)</span>?</span> (Optimalizaci převedeme přidáním omezení <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(c^{\\top}x\\le k\\)</span>.)</span></p>","u":"@R/ch-cisla/ch-cisla-ilp.html#prob-ilp"},"prob-steiner":{"t":"Problém 11.7: <span class=\"arithmatex\">\\(\\prob{Steiner Tree}\\)</span> (Steinerův strom)","b":"<p><strong>Vstup:</strong> graf <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G=(V,E)\\)</span>,</span> množina <em>terminálů</em> <span class=\"arithmatex\">\\(R\\subseteq V\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> strom s nejvýše <span class=\"arithmatex\">\\(k\\)</span> hranami, který obsahuje všechny terminály?</p>","u":"@R/ch-cisla/ch-cisla-steineruv-strom.html#prob-steiner"},"prob-exactpath":{"t":"Problém 11.18: <span class=\"arithmatex\">\\(\\prob{Exact Path (DAG)}\\)</span>","b":"<p><strong>Vstup:</strong> orientovaný acyklický graf <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G\\)</span>,</span> vrcholy <span class=\"arithmatex\">\\(s,t\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje orientovaná cesta z <span class=\"arithmatex\">\\(s\\)</span> do <span class=\"arithmatex\">\\(t\\)</span> s <em>přesně</em> <span class=\"arithmatex\">\\(L\\)</span> hranami?</p>","u":"@R/ch-cisla/sec-podezrele.html#prob-exactpath"},"prob-wexactpath":{"t":"Problém 11.19: <span class=\"arithmatex\">\\(\\prob{Weighted Exact Path}\\)</span>","b":"<p><strong>Vstup:</strong> orientovaný acyklický graf <span class=\"arithmatex\">\\(G\\)</span> s nezápornými celočíselnými vahami hran (binárně), vrcholy <span class=\"arithmatex\">\\(s,t\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje cesta z <span class=\"arithmatex\">\\(s\\)</span> do <span class=\"arithmatex\">\\(t\\)</span> se součtem vah přesně <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\)</span>?</span></p>","u":"@R/ch-cisla/sec-podezrele.html#prob-wexactpath"},"prob-rsp":{"t":"Problém 11.20: <span class=\"arithmatex\">\\(\\prob{Restricted Shortest Path}\\)</span>","b":"<p><strong>Vstup:</strong> orientovaný graf, každá hrana <span class=\"arithmatex\">\\(e\\)</span> má délku <span class=\"arithmatex\">\\(\\ell(e)\\ge0\\)</span> a cenu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(p(e)\\ge0\\)</span>;</span> vrcholy <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(s,t\\)</span>,</span> meze <span class=\"arithmatex\">\\(L\\)</span> a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(P\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje cesta z <span class=\"arithmatex\">\\(s\\)</span> do <span class=\"arithmatex\">\\(t\\)</span> s délkou <span class=\"arithmatex\">\\(\\le L\\)</span> a zároveň cenou <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\le P\\)</span>?</span></p>","u":"@R/ch-cisla/sec-podezrele.html#prob-rsp"},"prob-powerss":{"t":"Problém 11.21: <span class=\"arithmatex\">\\(\\prob{Power Subset Sum}\\)</span>","b":"<p><strong>Vstup:</strong> čísla <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(b_1,\\dots,b_m\\)</span>,</span> každé je mocnina dvojky (mohou se opakovat), a cíl <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(T\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje podmnožina se součtem přesně <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(T\\)</span>?</span></p>","u":"@R/ch-cisla/sec-podezrele.html#prob-powerss"},"thm-powersshlad":{"t":"Věta 11.22 (Power Subset Sum je v <span class=\"arithmatex\">\\(\\PP\\)</span>)","b":"<p>Hladový algoritmus – seřaď kousky sestupně, <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(R:=T\\)</span>,</span> kousek <span class=\"arithmatex\">\\(2^j\\)</span> vezmi, pokud <span class=\"arithmatex\">\\(2^j\\le R\\)</span> (a sniž <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(R\\)</span>),</span> na konci odpověz ANO <span class=\"arithmatex\">\\(\\iff R=0\\)</span> – je korektní a běží v čase <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(O(m\\log m)\\)</span>.</span></p>","u":"@R/ch-cisla/sec-podezrele.html#thm-powersshlad"},"lem-vymena":{"t":"Lemma 11.23: Výměnné lemma","b":"<p>Mají-li mocniny dvojky <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(p_1\\ge p_2\\ge\\dots\\)</span>,</span> všechny <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\le2^j\\)</span>,</span> součet <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\ge2^j\\)</span>,</span> pak součet nějakého jejich <em>prefixu</em> je přesně <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(2^j\\)</span>.</span></p>","u":"@R/ch-cisla/sec-podezrele.html#lem-vymena"},"prob-balsplit":{"t":"Problém 11.24: <span class=\"arithmatex\">\\(\\prob{Balanced Split}\\)</span>","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(q\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze vrcholy rozdělit na <span class=\"arithmatex\">\\(q\\)</span> stejně velkých částí tak, aby žádná hrana nevedla mezi různými částmi? (Ekvivalentně: komponenty souvislosti lze seskupit do <span class=\"arithmatex\">\\(q\\)</span> skupin se stejným počtem vrcholů.)</p>","u":"@R/ch-cisla/sec-podezrele.html#prob-balsplit"},"prob-sat":{"t":"Problém 6.1: <span class=\"arithmatex\">\\(\\prob{SAT}\\)</span> (splnitelnost)","b":"<p><strong>Vstup:</strong> booleovská formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v konjunktivní normální formě (CNF).</p>\n<p><strong>Otázka:</strong> existuje pravdivostní ohodnocení proměnných, pro které je <span class=\"arithmatex\">\\(\\varphi\\)</span> splněna?</p>","u":"@R/ch-cook/ch-cook-cook-levinova-veta.html#prob-sat"},"thm-cooklevin":{"t":"Věta 6.2 (Cook–Levin, 1971)","b":"<p>Problém <span class=\"arithmatex\">\\(\\prob{SAT}\\)</span> je NP-úplný.</p>","u":"@R/ch-cook/ch-cook-cook-levinova-veta.html#thm-cooklevin"},"prob-dlazdickovani":{"t":"Problém 6.3: <span class=\"arithmatex\">\\(\\prob{Dlaždičkování}\\)</span>","b":"<p><strong>Vstup:</strong> množina typů dlaždic, rozměry obdélníkové plochy <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(n\\times m\\)</span>,</span> předbarvené okraje plochy.</p>\n<p><strong>Otázka:</strong> lze plochu vydláždit tak, aby barvy sousedících hran vždy souhlasily (i s okraji plochy)?</p>","u":"@R/ch-cook/ch-cook-cook-levinova-veta.html#prob-dlazdickovani"},"lem-lredtiling":{"t":"Lemma 6.5: <span class=\"arithmatex\">\\(L\\redp{}\\)</span> Dlaždičkování","b":"<p>Mřížku s těmito okraji lze vydláždit zkonstruovanou sadou dlaždic <em>právě tehdy</em>, když existuje přijímající výpočet <span class=\"arithmatex\">\\(M\\)</span> na <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x\\)</span>.</span> Konstrukce je polynomiální: počet typů dlaždic závisí jen na (pevném) <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(M\\)</span>,</span> rozměry mřížky jsou polynomiální v <span class=\"arithmatex\">\\(|x|\\)</span> a okraje vypíšeme v polynomiálním čase.</p>","u":"@R/ch-cook/ch-cook-cook-levinova-veta.html#lem-lredtiling"},"cor-jaknpc":{"t":"Důsledek 6.6: Jak dokazovat NP-úplnost","b":"<p>Abychom ukázali, že <span class=\"arithmatex\">\\(Q\\)</span> je NP-úplný, stačí:</p>\n<ol><li>ukázat <span class=\"arithmatex\">\\(Q\\in\\NP\\)</span> (certifikát + polynomiální verifikátor),</li><li>najít známý NP-těžký problém <span class=\"arithmatex\">\\(A\\)</span> a polynomiální redukci <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(A\\redp Q\\)</span>.</span></li></ol>","u":"@R/ch-cook/ch-cook-karpuv-strom-princip-stafety.html#cor-jaknpc"},"prob-cliquer":{"t":"Problém 8.8: <span class=\"arithmatex\">\\(\\prob{Clique}\\)</span> (klika)","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> množina <span class=\"arithmatex\">\\(k\\)</span> vrcholů, z nichž každé dva jsou spojeny hranou?</p>","u":"@R/ch-is/ch-is-is-clique.html#prob-cliquer"},"lem-doplnek":{"t":"Lemma 8.9: Doplněk grafu","b":"<p><span class=\"arithmatex\">\\(S\\)</span> je nezávislá množina v <span class=\"arithmatex\">\\(G\\)</span> <span class=\"arithmatex\">\\(\\iff\\)</span> <span class=\"arithmatex\">\\(S\\)</span> je klika v doplňku <span class=\"arithmatex\">\\(\\overline G\\)</span> (vrcholy jsou v <span class=\"arithmatex\">\\(\\overline G\\)</span> spojeny právě tehdy, když v <span class=\"arithmatex\">\\(G\\)</span> spojeny nejsou).</p>","u":"@R/ch-is/ch-is-is-clique.html#lem-doplnek"},"cor-isclique":{"t":"Důsledek 8.10: <span class=\"arithmatex\">\\(\\prob{IS}\\redp\\prob{Clique}\\)</span>","b":"<p><span class=\"woo-nobr\"><span class=\"arithmatex\">\\((G,k)\\mapsto(\\overline G,k)\\)</span>.</span> Doplněk sestrojíme v čase <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(O(|V|^2)\\)</span>,</span> takže <span class=\"arithmatex\">\\(\\prob{Clique}\\)</span> je NP-úplný.</p>","u":"@R/ch-is/ch-is-is-clique.html#cor-isclique"},"prob-is":{"t":"Problém 8.1: <span class=\"arithmatex\">\\(\\prob{Independent Set}\\)</span> (IS, nezávislá množina)","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(S\\subseteq V\\)</span>,</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(|S|\\ge k\\)</span>,</span> taková, že žádné dva vrcholy z <span class=\"arithmatex\">\\(S\\)</span> nejsou spojeny hranou?</p>","u":"@R/ch-is/ch-is-nezavisla-mnozina.html#prob-is"},"thm-isnpc":{"t":"Věta 8.2","b":"<p><span class=\"arithmatex\">\\(\\prob{IS}\\)</span> je NP-úplný.</p>","u":"@R/ch-is/ch-is-nezavisla-mnozina.html#thm-isnpc"},"prob-hs":{"t":"Problém 8.7: <span class=\"arithmatex\">\\(\\prob{Hitting Set}\\)</span> (zasažení množin)","b":"<p><strong>Vstup:</strong> univerzum <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(U\\)</span>,</span> systém podmnožin <span class=\"arithmatex\">\\(\\mathcal S=\\{S_1,\\dots,S_m\\}\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze vybrat <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(H\\subseteq U\\)</span>,</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(|H|\\le k\\)</span>,</span> které protne každou množinu (<span class=\"arithmatex\">\\(H\\cap S_i\\neq\\emptyset\\)</span> pro všechna <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(i\\)</span>)?</span></p>","u":"@R/ch-is/ch-is-vc-hitting-set.html#prob-hs"},"prob-vc":{"t":"Problém 8.4: <span class=\"arithmatex\">\\(\\prob{Vertex Cover}\\)</span> (VC, vrcholové pokrytí)","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(c\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(C\\subseteq V\\)</span>,</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(|C|\\le c\\)</span>,</span> taková, že každá hrana má alespoň jeden konec v <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(C\\)</span>?</span></p>","u":"@R/ch-is/ch-is-vertex-cover.html#prob-vc"},"lem-isvc":{"t":"Lemma 8.5: Identita IS a VC","b":"<p><span class=\"arithmatex\">\\(S\\subseteq V\\)</span> je nezávislá množina <span class=\"arithmatex\">\\(\\iff\\)</span> <span class=\"arithmatex\">\\(V\\setminus S\\)</span> je vrcholové pokrytí.</p>","u":"@R/ch-is/ch-is-vertex-cover.html#lem-isvc"},"cor-isredvc":{"t":"Důsledek 8.6: <span class=\"arithmatex\">\\(\\prob{IS}\\redp\\prob{VC}\\)</span>","b":"<p>Instance <span class=\"arithmatex\">\\((G,k)\\)</span> IS se zobrazí na instanci <span class=\"arithmatex\">\\((G,\\ c=|V|-k)\\)</span> VC ve stejném grafu.</p>","u":"@R/ch-is/ch-is-vertex-cover.html#cor-isredvc"},"def-ndts-acc":{"t":"Definice 4.2: Přijetí a zamítnutí slova NDTS","b":"<ul><li>Slovo <span class=\"arithmatex\">\\(x\\)</span> je <strong>přijato</strong>, pokud <strong>existuje alespoň jeden</strong> výpočet (cesta od kořene k listu), který skončí ve stavu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\qA\\)</span>.</span></li><li>Slovo <span class=\"arithmatex\">\\(x\\)</span> je <strong>zamítnuto</strong>, pokud <strong>žádná</strong> větev nekončí v <span class=\"arithmatex\">\\(\\qA\\)</span> (všechny končí v <span class=\"arithmatex\">\\(\\qR\\)</span> nebo se zaseknou).</li></ul>","u":"@R/ch-np/ch-np-asymetrie-prijimani.html#def-ndts-acc"},"prob-composites":{"t":"Problém 4.13: <span class=\"arithmatex\">\\(\\prob{Composites}\\)</span>","b":"<p><strong>Vstup:</strong> přirozené číslo <span class=\"arithmatex\">\\(n\\)</span> zapsané binárně.</p>\n<p><strong>Otázka:</strong> je <span class=\"arithmatex\">\\(n\\)</span> složené?</p>","u":"@R/ch-np/ch-np-jak-navrhovat-nedeterministicke-stroje.html#prob-composites"},"prob-clique":{"t":"Problém 4.14: <span class=\"arithmatex\">\\(\\prob{Clique}\\)</span>","b":"<p><strong>Vstup:</strong> graf <span class=\"arithmatex\">\\(G\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>.</span></p>\n<p><strong>Otázka:</strong> obsahuje <span class=\"arithmatex\">\\(G\\)</span> kliku velikosti alespoň <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>?</span></p>","u":"@R/ch-np/ch-np-jak-navrhovat-nedeterministicke-stroje.html#prob-clique"},"def-ndts":{"t":"Definice 4.1: Nedeterministický Turingův stroj","b":"<p>NDTS s <span class=\"arithmatex\">\\(k\\)</span> páskami je devítice <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(M=(Q,\\Sigma,G,B,k,\\delta,q_0,\\qA,\\qR)\\)</span>,</span> kde</p>\n<ul><li><span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Q\\)</span>,</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\Sigma\\)</span>,</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G\\supsetneq\\Sigma\\)</span>,</span> <span class=\"arithmatex\">\\(B\\in G\\setminus\\Sigma\\)</span> (blank) a <span class=\"arithmatex\">\\(k\\ge1\\)</span> mají stejný význam jako u DTS (definice <a href=\"@R/ch-ts/ch-ts-turinguv-stroj.html#def-dts\">1.5</a>),</li><li><span class=\"arithmatex\">\\(q_0\\in Q\\)</span> je počáteční stav,</li><li><span class=\"arithmatex\">\\(\\qA\\in Q\\)</span> je <strong>přijímací</strong> a <span class=\"arithmatex\">\\(\\qR\\in Q\\)</span> <strong>zamítací</strong> stav (<span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\qA\\neq\\qR\\)</span>),</span></li><li><span class=\"arithmatex\">\\(\\delta\\subseteq \\bigl(Q\\times G^k\\bigr)\\times\\bigl(Q\\times G^k\\times\\{\\Lft,\\Stay,\\Rgt\\}^k\\bigr)\\)</span> je <strong>přechodová relace</strong>.</li></ul>","u":"@R/ch-np/ch-np-od-determinismu-k-nedeterminismu.html#def-ndts"},"def-verifikator":{"t":"Definice 4.7: Verifikátor","b":"<p><strong>Verifikátor</strong> pro jazyk <span class=\"arithmatex\">\\(L\\)</span> je deterministický TS <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(V\\)</span>,</span> který kromě vstupu <span class=\"arithmatex\">\\(x\\)</span> dostává dodatečnou informaci <span class=\"arithmatex\">\\(c\\)</span> – <strong>certifikát</strong> (svědka). <span class=\"arithmatex\">\\(V\\)</span> <em>přijímá</em> vstup <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x\\)</span>,</span> pokud existuje certifikát <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(c\\)</span>,</span> pro který <span class=\"arithmatex\">\\(V(x,c)\\)</span> přijme.</p>\n<p><span class=\"arithmatex\">\\(V\\)</span> je <strong>polynomiální verifikátor</strong>, pokud pracuje v čase polynomiálním vzhledem k <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(|x|\\)</span>.</span></p>","u":"@R/ch-np/ch-np-od-hadani-k-overovani-certifikaty.html#def-verifikator"},"def-nphat":{"t":"Definice 4.8: Certifikátová definice – třída <span class=\"arithmatex\">\\(\\NPhat\\)</span>","b":"<p>Jazyk <span class=\"arithmatex\">\\(L\\)</span> patří do třídy <span class=\"arithmatex\">\\(\\NPhat\\)</span> právě tehdy, když existuje polynomiální verifikátor <span class=\"arithmatex\">\\(V\\)</span> a polynom <span class=\"arithmatex\">\\(p\\)</span> takové, že</p>\n<div class=\"arithmatex\">\\[x\\in L \\iff \\exists c\\in\\Sigma^*:\\ |c|\\le p(|x|)\\ \\wedge\\ V(x,c)\\text{ přijme}.\\]</div>","u":"@R/ch-np/ch-np-od-hadani-k-overovani-certifikaty.html#def-nphat"},"prob-sat-np":{"t":"Problém 4.9: <span class=\"arithmatex\">\\(\\prob{SAT}\\)</span> (booleovská splnitelnost)","b":"<p><strong>Vstup:</strong> booleovská formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v konjunktivní normální formě (CNF).</p>\n<p><strong>Otázka:</strong> existuje ohodnocení proměnných, při kterém je <span class=\"arithmatex\">\\(\\varphi\\)</span> pravdivá?</p>","u":"@R/ch-np/ch-np-od-hadani-k-overovani-certifikaty.html#prob-sat-np"},"thm-np-eq":{"t":"Věta 4.11 (Ekvivalence definic)","b":"<p>Jazyk <span class=\"arithmatex\">\\(L\\)</span> je rozhodován polynomiálním NDTS (<span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\in\\NP\\)</span>)</span> <span class=\"arithmatex\">\\(\\iff\\)</span> <span class=\"arithmatex\">\\(L\\)</span> má deterministický polynomiální verifikátor (<span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\in\\NPhat\\)</span>).</span></p>","u":"@R/ch-np/ch-np-od-hadani-k-overovani-certifikaty.html#thm-np-eq"},"def-ntime":{"t":"Definice 4.4: Časová složitost NDTS a třída <span class=\"arithmatex\">\\(\\NTIME\\)</span>","b":"<p>NDTS <span class=\"arithmatex\">\\(M\\)</span> pracuje v čase <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(T_M(n)\\)</span>,</span> pokud pro každý vstup délky <span class=\"arithmatex\">\\(n\\)</span> <strong>každá větev</strong> jeho stromu výpočtu skončí po nejvýše <span class=\"arithmatex\">\\(T_M(n)\\)</span> krocích.</p>\n<p><span class=\"arithmatex\">\\(L\\in\\NTIME(f) \\iff\\)</span> existuje konstanta <span class=\"arithmatex\">\\(c\\in\\N\\)</span> a NDTS <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(M\\)</span>,</span> který rozhoduje <span class=\"arithmatex\">\\(L\\)</span> a pracuje v čase <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(c\\cdot f(n)\\)</span>.</span> Základní třídy:</p>\n<div class=\"arithmatex\">\\[\\NP = \\bigcup_{d=1}^{\\infty}\\NTIME(n^d)\\quad\\text{(Nondeterministic Polynomial time)},\\qquad \\NEXP = \\bigcup_{d=1}^{\\infty}\\NTIME\\bigl(2^{n^d}\\bigr).\\]</div>","u":"@R/ch-np/ch-np-tridy-nedeterministicke-casove-slozitosti.html#def-ntime"},"lem-np-exp":{"t":"Lemma 4.5: <span class=\"arithmatex\">\\(\\NP\\subseteq\\EXP\\)</span>","b":"<p>Každý jazyk rozhodnutelný nedeterministicky v polynomiálním čase lze rozhodnout deterministicky v exponenciálním čase.</p>","u":"@R/ch-np/ch-np-tridy-nedeterministicke-casove-slozitosti.html#lem-np-exp"},"thm-nhier":{"t":"Věta 4.6 (Nedeterministická časová hierarchie)","b":"<p>Nechť <span class=\"arithmatex\">\\(f,g\\colon\\N\\to\\N\\)</span> jsou časově konstruovatelné a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f(n+1)=o(g(n))\\)</span>.</span> Pak</p>\n<div class=\"arithmatex\">\\[\\NTIME(f(n))\\subsetneq\\NTIME(g(n)).\\]</div>","u":"@R/ch-np/ch-np-tridy-nedeterministicke-casove-slozitosti.html#thm-nhier"},"def-scc":{"t":"Definice 12.13: Silná souvislost, kondenzace","b":"<p>Nechť <span class=\"arithmatex\">\\(G=(V,E)\\)</span> je orientovaný graf. Vrcholy <span class=\"arithmatex\">\\(u,v\\)</span> jsou <em>silně propojené</em> (<span class=\"woo-nobr\"><span class=\"arithmatex\">\\(u\\sim v\\)</span>),</span> pokud vede orientovaná cesta z <span class=\"arithmatex\">\\(u\\)</span> do <span class=\"arithmatex\">\\(v\\)</span> i z <span class=\"arithmatex\">\\(v\\)</span> do <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(u\\)</span>.</span> Relace <span class=\"arithmatex\">\\(\\sim\\)</span> je ekvivalence (cesta délky 0; symetrie z definice; skládání cest); její třídy jsou <em>silně souvislé komponenty</em> (SCC).</p>\n<p><em>Kondenzace</em> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G\\)</span>:</span> vrcholy jsou SCC, hrana <span class=\"arithmatex\">\\(C\\to C'\\)</span> (<span class=\"woo-nobr\"><span class=\"arithmatex\">\\(C\\neq C'\\)</span>),</span> pokud v <span class=\"arithmatex\">\\(G\\)</span> vede hrana z nějakého <span class=\"arithmatex\">\\(u\\in C\\)</span> do nějakého <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(v\\in C'\\)</span>.</span> <em>Topologické uspořádání</em> <span class=\"arithmatex\">\\(\\prec\\)</span> je lineární uspořádání vrcholů, v němž každá hrana vede „doprava“; existuje právě pro acyklické grafy (DAG).</p>","u":"@R/ch-prostor/ch-prostor-2-sat-je-v-p.html#def-scc"},"lem-skew":{"t":"Lemma 12.14: Šikmá symetrie (skew symmetry)","b":"<p>Hrana <span class=\"arithmatex\">\\(a\\to b\\)</span> je v <span class=\"arithmatex\">\\(G_\\varphi\\)</span> právě tehdy, když je v něm i hrana <span class=\"arithmatex\">\\(\\lnot b\\to\\lnot a\\)</span> (obě vzniknou ze téže klauzule). Důsledky: cesta <span class=\"arithmatex\">\\(a\\leadsto b\\)</span> znamená cestu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\lnot b\\leadsto\\lnot a\\)</span>;</span> SCC přicházejí v zrcadlových párech <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(C\\leftrightarrow\\lnot C\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-2-sat-je-v-p.html#lem-skew"},"lem-donuceni":{"t":"Lemma 12.15: Cesta = řetěz donucení","b":"<p>Existuje-li v <span class=\"arithmatex\">\\(G_\\varphi\\)</span> cesta <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(a\\leadsto b\\)</span>,</span> pak každé splňující přiřazení s <span class=\"arithmatex\">\\(a=1\\)</span> má také <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(b=1\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-2-sat-je-v-p.html#lem-donuceni"},"thm-2sat":{"t":"Věta 12.16 (O rozdílnosti komponent)","b":"<p>Formule <span class=\"arithmatex\">\\(\\varphi\\)</span> v 2-CNF je splnitelná <span class=\"arithmatex\">\\(\\iff\\)</span> pro každou proměnnou <span class=\"arithmatex\">\\(x\\)</span> leží <span class=\"arithmatex\">\\(x\\)</span> a <span class=\"arithmatex\">\\(\\lnot x\\)</span> v různých silně souvislých komponentách implikačního grafu.</p>","u":"@R/ch-prostor/ch-prostor-2-sat-je-v-p.html#thm-2sat"},"cor-2satlin":{"t":"Důsledek 12.17: 2-SAT v lineárním čase","b":"<p>Test splnitelnosti 2-CNF = test „nejsou <span class=\"arithmatex\">\\(x,\\lnot x\\)</span> ve stejné SCC?“ – a ten umíme lineárně. Splňující ohodnocení dostaneme z topologického uspořádání kondenzace.</p>","u":"@R/ch-prostor/ch-prostor-2-sat-je-v-p.html#cor-2satlin"},"def-conp":{"t":"Definice 12.11: Doplněk jazyka, třída coNP","b":"<p>Doplněk jazyka <span class=\"arithmatex\">\\(Q\\)</span> je <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\overline Q=\\Sigma^*\\setminus Q\\)</span>.</span> Pak</p>\n<div class=\"arithmatex\">\\[\\coNP=\\{\\,Q\\mid \\overline Q\\in\\NP\\,\\},\\]</div>\n<p>obdobně <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\coNL\\)</span>,</span> … pro každou třídu.</p>","u":"@R/ch-prostor/ch-prostor-doplnky-jazyku-conp-a-conl.html#def-conp"},"thm-immerman":{"t":"Věta 12.12 (Immerman &amp; Szelepcsényi, 1987)","b":"<p><span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\NL=\\coNL\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-doplnky-jazyku-conp-a-conl.html#thm-immerman"},"def-lnl":{"t":"Definice 12.8: Třídy L a NL","b":"<p><span class=\"arithmatex\">\\(\\LL=\\DSPACE(\\log n)\\)</span> (deterministický logaritmický prostor), <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\NL=\\NSPACE(\\log n)\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-logaritmicky-prostor-l-a-nl.html#def-lnl"},"prob-streach":{"t":"Problém 12.9: <span class=\"arithmatex\">\\(\\prob{ST-REACH}\\)</span> (dosažitelnost v orientovaném grafu)","b":"<p><strong>Vstup:</strong> orientovaný graf <span class=\"arithmatex\">\\(G\\)</span> a vrcholy <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(s,t\\)</span>.</span></p>\n<p><strong>Otázka:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> orientovaná cesta z <span class=\"arithmatex\">\\(s\\)</span> do <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(t\\)</span>?</span></p>","u":"@R/ch-prostor/ch-prostor-logaritmicky-prostor-l-a-nl.html#prob-streach"},"thm-nlp":{"t":"Věta 12.10","b":"<p><span class=\"arithmatex\">\\(\\LL\\subseteq\\NL\\subseteq\\PP\\)</span> a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\NL\\subseteq\\DSPACE(\\log^2 n)\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-logaritmicky-prostor-l-a-nl.html#thm-nlp"},"def-prostor":{"t":"Definice 12.1: Prostorová složitost","b":"<p>Nechť <span class=\"arithmatex\">\\(M\\)</span> je Turingův stroj. Říkáme, že <span class=\"arithmatex\">\\(M\\)</span> <em>pracuje v prostoru</em> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(S(n)\\)</span>,</span> pokud pro každý vstup délky <span class=\"arithmatex\">\\(n\\)</span> navštíví nejvýše <span class=\"arithmatex\">\\(S(n)\\)</span> buněk na svých pracovních páskách.</p>\n<ul><li><span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\DSPACE(S(n))\\)</span>:</span> problémy řešitelné deterministicky v prostoru <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(O(S(n))\\)</span>,</span></li><li><span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\NSPACE(S(n))\\)</span>:</span> problémy řešitelné nedeterministicky v prostoru <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(O(S(n))\\)</span>,</span></li><li><span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\PSPACE=\\bigcup_{k\\ge1}\\DSPACE(n^k)\\)</span>,</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\NPSPACE=\\bigcup_{k\\ge1}\\NSPACE(n^k)\\)</span>.</span></li></ul>","u":"@R/ch-prostor/ch-prostor-prostorove-tridy.html#def-prostor"},"def-prostor-konstr":{"t":"Definice 12.2: Prostorová konstruovatelnost","b":"<p>Funkce <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f:\\N\\to\\N\\)</span>,</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f(n)\\ge\\log n\\)</span>,</span> je <em>prostorově konstruovatelná</em>, pokud existuje Turingův stroj, který na vstup <span class=\"arithmatex\">\\(1^n\\)</span> spočítá (binárně) hodnotu <span class=\"arithmatex\">\\(f(n)\\)</span> v prostoru <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(O(f(n))\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-prostorove-tridy.html#def-prostor-konstr"},"thm-prostorhier":{"t":"Věta 12.3 (Prostorová hierarchie; Stearns, Hartmanis, Lewis 1965)","b":"<p>Nechť <span class=\"arithmatex\">\\(f,g\\)</span> jsou prostorově konstruovatelné a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f(n)=o(g(n))\\)</span>.</span> Pak <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\DSPACE(f(n))\\subsetneq\\DSPACE(g(n))\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-prostorove-tridy.html#thm-prostorhier"},"lem-casprostor":{"t":"Lemma 12.4: Čas omezuje prostor","b":"<p><span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\DTIME(f(n))\\subseteq\\DSPACE(f(n))\\)</span>,</span> a tedy <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\PP\\subseteq\\PSPACE\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-prostorove-tridy.html#lem-casprostor"},"lem-nppspace":{"t":"Lemma 12.5: <span class=\"arithmatex\">\\(\\NP\\subseteq\\PSPACE\\)</span>","b":"<p>Každý problém z <span class=\"arithmatex\">\\(\\NP\\)</span> lze rozhodnout deterministicky v polynomiálním prostoru.</p>","u":"@R/ch-prostor/ch-prostor-prostorove-tridy.html#lem-nppspace"},"cor-zacykleni":{"t":"Důsledek 12.6: Zacyklení","b":"<p>Běží-li deterministický stroj v prostoru <span class=\"arithmatex\">\\(S(n)\\)</span> déle než <span class=\"arithmatex\">\\(2^{O(S(n))}\\)</span> kroků, musel zopakovat konfiguraci, a tedy se zacyklil. Proto <span class=\"arithmatex\">\\(\\DSPACE(S(n))\\subseteq\\DTIME(2^{O(S(n))})\\)</span> a speciálně</p>\n<div class=\"arithmatex\">\\[\\PSPACE\\subseteq\\EXP .\\]</div>\n<p>(Stroj můžeme po exponenciálním čase násilně zastavit – kdyby měl přijmout, už by to udělal.)</p>","u":"@R/ch-prostor/ch-prostor-prostorove-tridy.html#cor-zacykleni"},"thm-savitch":{"t":"Věta 12.7 (Walter Savitch, 1970)","b":"<p>Pro každou prostorově konstruovatelnou funkci <span class=\"arithmatex\">\\(S(n)\\ge\\log n\\)</span> platí</p>\n<div class=\"arithmatex\">\\[\\NSPACE(S(n))\\subseteq\\DSPACE(S^2(n)).\\]</div>\n<p>Speciálně <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\PSPACE=\\NPSPACE\\)</span>.</span></p>","u":"@R/ch-prostor/ch-prostor-savitchova-veta.html#thm-savitch"},"prob-tqbf":{"t":"Problém 13.2: <span class=\"arithmatex\">\\(\\prob{TQBF}\\)</span> (True Quantified Boolean Formula)","b":"<p><strong>Vstup:</strong> plně kvantifikovaná formule <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\Psi=Q_1x_1\\,Q_2x_2\\dots Q_nx_n:\\ \\varphi(x_1,\\dots,x_n)\\)</span>,</span> kde <span class=\"arithmatex\">\\(Q_i\\in\\{\\exists,\\forall\\}\\)</span> a <span class=\"arithmatex\">\\(\\varphi\\)</span> je booleovská formule.</p>\n<p><strong>Otázka:</strong> je <span class=\"arithmatex\">\\(\\Psi\\)</span> pravdivá?</p>","u":"@R/ch-pspace/ch-pspace-tqbf.html#prob-tqbf"},"thm-tqbfpspace":{"t":"Věta 13.3 (Stockmeyer, Meyer 1973)","b":"<p><span class=\"arithmatex\">\\(\\prob{TQBF}\\)</span> je <span class=\"arithmatex\">\\(\\PSPACE\\)</span>-úplný.</p>","u":"@R/ch-pspace/ch-pspace-tqbf.html#thm-tqbfpspace"},"def-pspaceuplny":{"t":"Definice 13.1: PSPACE-úplnost","b":"<p>Problém <span class=\"arithmatex\">\\(X\\)</span> je <em><span class=\"arithmatex\">\\(\\PSPACE\\)</span>-úplný</em>, pokud</p>\n<ol><li><span class=\"arithmatex\">\\(X\\in\\PSPACE\\)</span> a</li><li>pro každý problém <span class=\"arithmatex\">\\(Y\\in\\PSPACE\\)</span> existuje polynomiální redukce <span class=\"arithmatex\">\\(Y\\redp X\\)</span> (<em><span class=\"arithmatex\">\\(\\PSPACE\\)</span>-těžkost</em>).</li></ol>","u":"@R/ch-pspace/index.html#def-pspaceuplny"},"prob-gg":{"t":"Problém 13.4: <span class=\"arithmatex\">\\(\\prob{Generalized Geography}\\)</span> (GG)","b":"<p><strong>Vstup:</strong> orientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a startovní vrchol <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(s\\)</span>.</span></p>\n<p><strong>Hra:</strong> žeton stojí v <span class=\"arithmatex\">\\(s\\)</span> (<span class=\"arithmatex\">\\(s\\)</span> je navštívený). Alice a Bob se střídají, začíná Alice. Tah = posun žetonu po hraně do <em>nenavštíveného</em> vrcholu. Kdo nemůže táhnout, prohrál.</p>\n<p><strong>Otázka:</strong> má Alice vítěznou strategii?</p>","u":"@R/ch-pspace/sec-geografie.html#prob-gg"},"thm-ggpspace":{"t":"Věta 13.5 (Schaefer 1978)","b":"<p><span class=\"arithmatex\">\\(\\prob{Generalized Geography}\\)</span> je <span class=\"arithmatex\">\\(\\PSPACE\\)</span>-úplná.</p>","u":"@R/ch-pspace/sec-geografie.html#thm-ggpspace"},"thm-ugg":{"t":"Věta 13.6","b":"<p>Alice vyhraje <span class=\"arithmatex\">\\(\\iff\\)</span> vrchol <span class=\"arithmatex\">\\(s\\)</span> je pokrytý <em>každým</em> největším párováním grafu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G\\)</span>.</span></p>","u":"@R/ch-pspace/sec-geografie.html#thm-ugg"},"cor-uggp":{"t":"Důsledek 13.7: Neorientovaná geografie je v <span class=\"arithmatex\">\\(\\PP\\)</span>","b":"<p>Označme <span class=\"arithmatex\">\\(\\nu(H)\\)</span> velikost největšího párování grafu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(H\\)</span>.</span> Vrchol <span class=\"arithmatex\">\\(s\\)</span> je v každém největším párování <span class=\"arithmatex\">\\(\\iff\\nu(G-s)&lt;\\nu(G)\\)</span> (párování grafu <span class=\"arithmatex\">\\(G-s\\)</span> jsou přesně párování <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G\\)</span>,</span> která nepokrývají <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(s\\)</span>).</span> Největší párování najdeme v polynomiálním čase (Edmondsův algoritmus), stačí dvakrát spočítat <span class=\"arithmatex\">\\(\\nu\\)</span> a porovnat.</p>","u":"@R/ch-pspace/sec-geografie.html#cor-uggp"},"def-redukce":{"t":"Definice 5.1: Polynomiální (Karpova, many-one) redukce","b":"<p>Buďte <span class=\"arithmatex\">\\(L,Q\\subseteq\\Sigma^*\\)</span> jazyky. <strong>Polynomiální redukce</strong> z <span class=\"arithmatex\">\\(L\\)</span> do <span class=\"arithmatex\">\\(Q\\)</span> je funkce <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f\\colon\\Sigma^*\\to\\Sigma^*\\)</span>,</span> která</p>\n<ol><li>je počítatelná v polynomiálním čase (deterministickým TS),</li><li>pro každé <span class=\"arithmatex\">\\(x\\in\\Sigma^*\\)</span> splňuje <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\quad x\\in L \\iff f(x)\\in Q\\)</span>.</span></li></ol>\n<p>Značíme <span class=\"arithmatex\">\\(L\\redp Q\\)</span> a čteme „<span class=\"arithmatex\">\\(L\\)</span> se polynomiálně redukuje na <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Q\\)</span>“.</span></p>","u":"@R/ch-redukce/ch-redukce-jak-porovnat-slozitost-dvou-problemu.html#def-redukce"},"lem-redvlast":{"t":"Lemma 5.2: Základní vlastnosti redukcí","b":"<p>Buďte <span class=\"arithmatex\">\\(L,Q,R\\subseteq\\Sigma^*\\)</span> jazyky. Pak platí:</p>\n<ol><li><strong>Tranzitivita:</strong> pokud <span class=\"arithmatex\">\\(L\\redp Q\\)</span> a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Q\\redp R\\)</span>,</span> pak <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\redp R\\)</span>.</span></li><li><strong>Přenos řešitelnosti:</strong> pokud <span class=\"arithmatex\">\\(L\\redp Q\\)</span> a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Q\\in\\PP\\)</span>,</span> pak <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\in\\PP\\)</span>.</span></li><li><strong>Přenos neřešitelnosti:</strong> pokud <span class=\"arithmatex\">\\(L\\redp Q\\)</span> a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\notin\\PP\\)</span>,</span> pak <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Q\\notin\\PP\\)</span>.</span></li></ol>","u":"@R/ch-redukce/ch-redukce-jak-porovnat-slozitost-dvou-problemu.html#lem-redvlast"},"def-nphard":{"t":"Definice 5.3: NP-těžký a NP-úplný jazyk","b":"<ul><li>Jazyk <span class=\"arithmatex\">\\(Q\\)</span> je <strong>NP-těžký</strong> (NP-hard), pokud <span class=\"arithmatex\">\\(L\\redp Q\\)</span> pro <em>všechny</em> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L\\in\\NP\\)</span>.</span></li><li>Jazyk <span class=\"arithmatex\">\\(Q\\)</span> je <strong>NP-úplný</strong> (NP-complete), pokud je NP-těžký <em>a zároveň</em> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Q\\in\\NP\\)</span>.</span></li></ul>","u":"@R/ch-redukce/ch-redukce-np-tezkost-a-np-uplnost.html#def-nphard"},"thm-gral":{"t":"Věta 5.4 (Svatý grál teorie složitosti)","b":"<p>Nechť <span class=\"arithmatex\">\\(Q\\)</span> je libovolný NP-úplný problém. Pak <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Q\\in\\PP \\iff \\PP=\\NP\\)</span>.</span></p>","u":"@R/ch-redukce/ch-redukce-np-tezkost-a-np-uplnost.html#thm-gral"},"prob-unp":{"t":"Problém 5.5: <span class=\"arithmatex\">\\(\\prob{UNP}\\)</span> – univerzální jazyk pro <span class=\"arithmatex\">\\(\\NP\\)</span>","b":"<p><strong>Vstup:</strong> kód nedeterministického stroje <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(M\\)</span>,</span> vstupní slovo <span class=\"arithmatex\">\\(x\\)</span> a číslo <span class=\"arithmatex\">\\(k\\)</span> zapsané <em>unárně</em>, tedy jako řetízek <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(1^k=\\underbrace{11\\dots1}_{k}\\)</span>.</span></p>\n<p><strong>Otázka:</strong> přijme stroj <span class=\"arithmatex\">\\(M\\)</span> slovo <span class=\"arithmatex\">\\(x\\)</span> během nejvýše <span class=\"arithmatex\">\\(k\\)</span> kroků (tj. existuje přijímající větev délky <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\le k\\)</span>)?</span></p>","u":"@R/ch-redukce/ch-redukce-np-tezkost-a-np-uplnost.html#prob-unp"},"thm-unpnpc":{"t":"Věta 5.6","b":"<p><span class=\"arithmatex\">\\(\\prob{UNP}\\)</span> je NP-úplný.</p>","u":"@R/ch-redukce/ch-redukce-np-tezkost-a-np-uplnost.html#thm-unpnpc"},"ch-resice-ilp-def-gap":{"t":"Definice 15.19: Optimality gap","b":"<div class=\"arithmatex\">\\[\\text{gap}=\\frac{B-z}{|z|} .\\]</div>\n<p>Platí <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(z\\le\\mathrm{OPT}\\le B\\)</span>.</span> <strong>Gap <span class=\"arithmatex\">\\(=0\\)</span> je certifikát optimality</strong>; po časovém limitu máme aspoň garanci „nejhůř o gap·100 % od optima“.</p>","u":"@R/ch-resice-ilp/ch-resice-ilp-branch-and-bound.html#ch-resice-ilp-def-gap"},"ch-resice-ilp-def-lp-relaxace":{"t":"Definice 15.7: LP relaxace","b":"<p><strong>LP relaxace</strong> ILP vznikne zrušením celočíselnosti: <span class=\"arithmatex\">\\(x\\in\\mathbb Z^n\\)</span> nahradíme <span class=\"arithmatex\">\\(x\\in\\mathbb R^n\\)</span> (binární <span class=\"arithmatex\">\\(x\\in\\{0,1\\}\\)</span> nahradíme <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(0\\le x\\le1\\)</span>).</span> Přípustná množina relaxace je <strong>polyedr</strong> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(P=\\{x\\in\\mathbb R^n: Ax\\le b\\}\\)</span>.</span> Hodnotu jejího optima značíme <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\mathrm{OPT}_{LP}\\)</span>.</span></p>","u":"@R/ch-resice-ilp/ch-resice-ilp-lp-relaxace-a-dualita.html#ch-resice-ilp-def-lp-relaxace"},"ch-resice-ilp-def-dual":{"t":"Definice 15.10: Primál a duál","b":"<table><thead><tr><th style=\"text-align:left\">Primál (max)</th><th style=\"text-align:left\">Duál (min)</th></tr></thead><tbody><tr><td style=\"text-align:left\"><span class=\"arithmatex\">\\(\\max\\ c^Tx\\)</span> při <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(Ax\\le b\\)</span>,</span> <span class=\"arithmatex\">\\(x\\ge0\\)</span></td><td style=\"text-align:left\"><span class=\"arithmatex\">\\(\\min\\ b^Ty\\)</span> při <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(A^Ty\\ge c\\)</span>,</span> <span class=\"arithmatex\">\\(y\\ge0\\)</span></td></tr></tbody></table>\n<p>Omezení primálu <span class=\"arithmatex\">\\(\\leftrightarrow\\)</span> proměnná duálu; <span class=\"arithmatex\">\\(c\\)</span> a <span class=\"arithmatex\">\\(b\\)</span> si vymění role; <span class=\"arithmatex\">\\(A\\)</span> se transponuje.</p>","u":"@R/ch-resice-ilp/ch-resice-ilp-lp-relaxace-a-dualita.html#ch-resice-ilp-def-dual"},"ch-resice-ilp-thm-slaba-dualita":{"t":"Věta 15.11 (Slabá dualita)","b":"<p>Pro každé přípustné <span class=\"arithmatex\">\\(x\\)</span> primálu a přípustné <span class=\"arithmatex\">\\(y\\)</span> duálu platí <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(c^Tx\\le b^Ty\\)</span>.</span></p>","u":"@R/ch-resice-ilp/ch-resice-ilp-lp-relaxace-a-dualita.html#ch-resice-ilp-thm-slaba-dualita"},"ch-resice-ilp-thm-silna-dualita":{"t":"Věta 15.12 (Silná dualita (bez důkazu))","b":"<p>Má-li primál konečné optimum, má ho i duál a obě hodnoty se rovnají: <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\max c^Tx=\\min b^Ty\\)</span>.</span></p>","u":"@R/ch-resice-ilp/ch-resice-ilp-lp-relaxace-a-dualita.html#ch-resice-ilp-thm-silna-dualita"},"ch-resice-ilp-def-ilp":{"t":"Definice 15.1: Celočíselné lineární programování (ILP)","b":"<div class=\"arithmatex\">\\[\\max\\ c^{T}x\\quad\\text{za podmínek}\\quad Ax\\le b,\\quad x\\in\\mathbb Z^{n}.\\]</div>\n<p>Omezení i účelová funkce jsou <em>lineární</em>, proměnné <em>celočíselné</em>.</p>\n<p><strong>Varianty:</strong></p>\n<ul><li><strong>0/1-ILP</strong>: <span class=\"arithmatex\">\\(x\\in\\{0,1\\}^n\\)</span> – každá proměnná je rozhodnutí ano/ne;</li><li><strong>MIP / MILP</strong> (mixed integer linear programming): celočíselné jsou jen <em>některé</em> proměnné, ostatní jsou reálné.</li></ul>","u":"@R/ch-resice-ilp/ch-resice-ilp-od-slov-k-modelu.html#ch-resice-ilp-def-ilp"},"ch-resice-ilp-def-terminologie":{"t":"Definice 15.2: Přípustné řešení, optimální řešení, optimum","b":"<p><strong>Přípustné řešení</strong> je <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x\\)</span>,</span> které splňuje všechna omezení. <strong>Optimální řešení</strong> je nejlepší přípustné řešení – je to <em>bod</em> a může jich být víc. <strong>Optimum</strong> <span class=\"arithmatex\">\\(\\mathrm{OPT}(I)\\)</span> je jeho hodnota na instanci <span class=\"arithmatex\">\\(I\\)</span> – je to <em>číslo</em>.</p>","u":"@R/ch-resice-ilp/ch-resice-ilp-od-slov-k-modelu.html#ch-resice-ilp-def-terminologie"},"ch-resice-ilp-def-rez":{"t":"Definice 15.21: Řez","b":"<p><strong>Řez</strong> je nerovnost, která platí pro <em>všechna</em> celočíselná řešení, ale <em>odřízne</em> aktuální LP optimum <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x^*\\)</span>.</span></p>","u":"@R/ch-resice-ilp/ch-resice-ilp-rezy-a-separace.html#ch-resice-ilp-def-rez"},"ch-resice-ilp-def-separacni-orakulum":{"t":"Definice 15.23: Separační orákulum","b":"<p><strong>Separační orákulum</strong> dostane <span class=\"arithmatex\">\\(x^*\\)</span> a buď najde platnou nerovnost, kterou <span class=\"arithmatex\">\\(x^*\\)</span> porušuje, nebo odpoví „žádná není“.</p>","u":"@R/ch-resice-ilp/ch-resice-ilp-rezy-a-separace.html#ch-resice-ilp-def-separacni-orakulum"},"ch-resice-ilp-def-integrality-gap":{"t":"Definice 15.14: Integrality gap","b":"<p><strong>Integrality gap</strong> formulace minimalizační úlohy je</p>\n<div class=\"arithmatex\">\\[\\mathrm{IG}=\\sup_I\\ \\frac{\\mathrm{OPT}(I)}{\\mathrm{OPT}_{LP}(I)}\\ \\ge\\ 1 ,\\]</div>\n<p>kde supremum je přes všechny instance <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(I\\)</span>.</span> Je to vlastnost <em>formulace</em>, ne problému.</p>","u":"@R/ch-resice-ilp/ch-resice-ilp-sila-formulace.html#ch-resice-ilp-def-integrality-gap"},"ch-resice-ilp-def-tu":{"t":"Definice 15.16: Totální unimodularita (TU)","b":"<p>Matice <span class=\"arithmatex\">\\(A\\)</span> je <strong>totálně unimodulární</strong>, jestliže každá její čtvercová podmatice má determinant v <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\{0,\\pm1\\}\\)</span>.</span></p>","u":"@R/ch-resice-ilp/ch-resice-ilp-sila-formulace.html#ch-resice-ilp-def-tu"},"ch-resice-ilp-thm-hoffman-kruskal":{"t":"Věta 15.17 (Hoffman–Kruskal 1956 (bez důkazu))","b":"<p>Je-li <span class=\"arithmatex\">\\(A\\)</span> TU a <span class=\"arithmatex\">\\(b\\)</span> celočíselné, pak všechny vrcholy polyedru <span class=\"arithmatex\">\\(\\{x: Ax\\le b,\\ x\\ge0\\}\\)</span> jsou celočíselné.</p>","u":"@R/ch-resice-ilp/ch-resice-ilp-sila-formulace.html#ch-resice-ilp-thm-hoffman-kruskal"},"ch-resice-sat-def-dpll":{"t":"Definice 14.10: DPLL (Davis–Putnam–Logemann–Loveland, 1962)","b":"<p>Rekurzivní prohledávání ohodnocení se dvěma pravidly:</p>\n<dl class=\"woo-dl\"><dt>Unit propagation:</dt><dd>klauzule má jediný nepřiřazený literál <span class=\"arithmatex\">\\(\\ell\\)</span> a ostatní její literály jsou nepravdivé <span class=\"arithmatex\">\\(\\Rightarrow\\)</span> nutně <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\ell=1\\)</span>.</span> Šíříme, dokud jde.</dd><dt>Větvení + konflikt:</dt><dd>nic nešíříme <span class=\"arithmatex\">\\(\\Rightarrow\\)</span> vybereme nepřiřazenou proměnnou <span class=\"arithmatex\">\\(x\\)</span> a zkusíme jednu hodnotu, pak druhou. Konflikt (klauzule se všemi literály nepravdivými) <span class=\"arithmatex\">\\(\\Rightarrow\\)</span> <em>backtrack</em> – návrat k poslednímu rozhodnutí, které má ještě nevyzkoušenou hodnotu.</dd></dl>","u":"@R/ch-resice-sat/ch-resice-sat-jak-funguji-sat-resice.html#ch-resice-sat-def-dpll"},"ch-resice-sat-def-implikacni-graf-cdcl":{"t":"Definice 14.12: Implikační graf CDCL","b":"<p>Vrcholy jsou přiřazení (<span class=\"woo-nobr\"><span class=\"arithmatex\">\\(a@1\\)</span>,</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(b@1\\)</span>,</span> …) a konflikt <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\bot\\)</span>;</span> hrana <span class=\"arithmatex\">\\(u\\to v\\)</span> s popiskem <span class=\"arithmatex\">\\(c_i\\)</span> znamená „přiřazení <span class=\"arithmatex\">\\(v\\)</span> vynutila klauzule <span class=\"arithmatex\">\\(c_i\\)</span> (mimo jiné kvůli <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(u\\)</span>)“.</span> Rozhodnutí nemají předchůdce.</p>","u":"@R/ch-resice-sat/ch-resice-sat-jak-funguji-sat-resice.html#ch-resice-sat-def-implikacni-graf-cdcl"},"ch-resice-sat-def-bloky":{"t":"Definice 14.15: Stavební bloky kódování","b":"<p>Pro proměnné <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(y_1,\\dots,y_n\\)</span>:</span></p>\n<dl class=\"woo-dl\"><dt>alespoň jedna (at-least-one):</dt><dd><span class=\"arithmatex\">\\(\\mathrm{ALO}(y_1,\\dots,y_n)=(y_1\\lor\\dots\\lor y_n)\\)</span> – jedna klauzule;</dd><dt>nejvýše jedna (at-most-one):</dt><dd><span class=\"arithmatex\">\\(\\mathrm{AMO}(y_1,\\dots,y_n)=\\bigwedge_{i&lt;j}(\\lnot y_i\\lor\\lnot y_j)\\)</span> – „žádné dvě zároveň“, <span class=\"arithmatex\">\\(\\binom n2\\)</span> klauzulí;</dd><dt>právě jedna (exactly-one):</dt><dd><span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\mathrm{EO}=\\mathrm{ALO}\\land\\mathrm{AMO}\\)</span>;</span></dd><dt>nejvýše <span class=\"arithmatex\">\\(k\\)</span> (at-most-<span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>):</span></dt><dd><span class=\"arithmatex\">\\(\\mathrm{AMK}_k(y_1,\\dots,y_n)\\)</span> – „žádných <span class=\"arithmatex\">\\(k+1\\)</span> zároveň“; přímo <span class=\"arithmatex\">\\(\\binom{n}{k+1}\\)</span> klauzulí, s pomocnými proměnnými <span class=\"arithmatex\">\\(O(nk)\\)</span> (cvičení <a href=\"@R/ch-resice-sat/ch-resice-sat-cviceni-7.html#cv-7-4\">7.4</a>).</dd></dl>\n<p>Zkratky ALO/AMO/EO/AMK jsou <em>(nad rámec přednášky)</em> – přednáška říká „alespoň jedna“, „nejvýše jedna“.</p>","u":"@R/ch-resice-sat/ch-resice-sat-redukce-do-sat.html#ch-resice-sat-def-bloky"},"ch-resice-sat-def-schur":{"t":"Problém 14.25: <span class=\"arithmatex\">\\(\\prob{Schur}\\)</span> a Schurovo číslo","b":"<p><strong>Vstup:</strong> čísla <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(n,k\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze čísla <span class=\"arithmatex\">\\(\\{1,2,\\dots,n\\}\\)</span> obarvit <span class=\"arithmatex\">\\(k\\)</span> barvami tak, aby žádná trojice <span class=\"arithmatex\">\\(x+y=z\\)</span> nebyla jednobarevná? (<span class=\"arithmatex\">\\(x=y\\)</span> je povoleno: <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(1+1=2\\)</span>.)</span></p>\n<p><strong>Schurovo číslo</strong> <span class=\"arithmatex\">\\(S(k)\\)</span> = největší <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(n\\)</span>,</span> pro které to jde.</p>","u":"@R/ch-resice-sat/ch-resice-sat-sat-resic-v-praxi.html#ch-resice-sat-def-schur"},"ch-resice-sat-def-smt":{"t":"Definice 14.23: SMT a architektura DPLL(T)","b":"<p><strong>SMT</strong> (Satisfiability Modulo Theories) spojuje SAT řešič se specializovanými <em>řešiči teorií</em> (aritmetika, pole, …). Architektura <strong>DPLL(T)</strong> pracuje ve čtyřech krocích:</p>\n<ol><li><strong>Abstrakce:</strong> atomy teorie nahradíme Booleovskými proměnnými, <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\varphi\\to\\varphi^B\\)</span>.</span></li><li><strong>SAT řešič:</strong> najde ohodnocení abstrakce <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\varphi^B\\)</span>.</span></li><li><strong>Řešič teorie:</strong> ověří, zda jsou pravdivé atomy konzistentní v teorii.</li><li><strong>Konflikt:</strong> teorie řekne „ne“ <span class=\"arithmatex\">\\(\\to\\)</span> SAT řešič se poučí (dostane klauzuli) a hledá dál.</li></ol>\n<p><strong>Líný přístup:</strong> teorie se <em>neenkóduje</em> předem, ptáme se jí za běhu.</p>","u":"@R/ch-resice-sat/ch-resice-sat-smt.html#ch-resice-sat-def-smt"},"ch-resice-sat-def-horn":{"t":"Definice 14.4: Hornova klauzule a formule","b":"<p>Klauzule je <strong>Hornova</strong>, pokud obsahuje <em>nejvýše jeden kladný</em> literál. Formule je Hornova, jsou-li všechny její klauzule Hornovy. Hornova klauzule má jeden ze tří tvarů (přepsáno jako implikace):</p>\n<table><tbody><tr><td style=\"text-align:left\"><span class=\"arithmatex\">\\((\\lnot x_1\\lor\\dots\\lor\\lnot x_k\\lor y)\\)</span></td><td style=\"text-align:left\"><span class=\"arithmatex\">\\(\\equiv\\ (x_1\\land\\dots\\land x_k)\\Rightarrow y\\)</span></td><td style=\"text-align:left\"><strong>pravidlo</strong></td></tr><tr><td style=\"text-align:left\"><span class=\"arithmatex\">\\((\\lnot x_1\\lor\\dots\\lor\\lnot x_k)\\)</span></td><td style=\"text-align:left\"><span class=\"arithmatex\">\\(\\equiv\\ (x_1\\land\\dots\\land x_k)\\Rightarrow\\bot\\)</span></td><td style=\"text-align:left\"><strong>omezující</strong> klauzule</td></tr><tr><td style=\"text-align:left\"><span class=\"arithmatex\">\\((y)\\)</span></td><td style=\"text-align:left\"><span class=\"arithmatex\">\\(\\equiv\\ \\top\\Rightarrow y\\)</span></td><td style=\"text-align:left\"><strong>fakt</strong></td></tr></tbody></table>","u":"@R/ch-resice-sat/ch-resice-sat-snadne-varianty-satu.html#ch-resice-sat-def-horn"},"ch-resice-sat-thm-horn":{"t":"Věta 14.6 (Korektnost: proč stačí hladovost)","b":"<p>Algoritmus <a href=\"@R/ch-resice-sat/ch-resice-sat-snadne-varianty-satu.html#ch-resice-sat-alg-horn\">14.1</a> odpoví NESPLNITELNÁ, právě když je Hornova formule nesplnitelná. Vrátí-li <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\tau\\)</span>,</span> je to splňující ohodnocení.</p>","u":"@R/ch-resice-sat/ch-resice-sat-snadne-varianty-satu.html#ch-resice-sat-thm-horn"},"ch-resice-sat-def-xor":{"t":"Definice 14.7: XOR klauzule","b":"<p><strong>XOR klauzule</strong> má tvar <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x_1\\oplus x_2\\oplus\\dots\\oplus x_k=b\\)</span>,</span> kde <span class=\"arithmatex\">\\(b\\in\\{0,1\\}\\)</span> a <span class=\"arithmatex\">\\(\\oplus\\)</span> je exkluzivní or (součet modulo 2). Problém <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\prob{XOR-SAT}\\)</span>:</span> je splnitelná konjunkce XOR klauzulí?</p>","u":"@R/ch-resice-sat/ch-resice-sat-snadne-varianty-satu.html#ch-resice-sat-def-xor"},"ch-resice-sat-thm-schaefer":{"t":"Věta 14.9 (Schaeferova dichotomie, Schaefer 1978)","b":"<p>Pro každou konečnou množinu <span class=\"arithmatex\">\\(\\Gamma\\)</span> povolených typů klauzulí je <span class=\"arithmatex\">\\(\\prob{SAT}(\\Gamma)\\)</span> buď v <span class=\"arithmatex\">\\(\\PP\\)</span> (jedna z 6 snadných rodin), nebo NP-úplný. Nic mezi tím. (Uvádíme bez důkazu.)</p>","u":"@R/ch-resice-sat/ch-resice-sat-snadne-varianty-satu.html#ch-resice-sat-thm-schaefer"},"ch-resice-sat-thm-tseitin":{"t":"Věta 14.22 (Tseitin, 1968)","b":"<p>Pro obvod <span class=\"arithmatex\">\\(\\varphi\\)</span> s <span class=\"arithmatex\">\\(m\\)</span> hradly sestrojíme v polynomiálním čase 3-CNF <span class=\"arithmatex\">\\(\\psi\\)</span> s <span class=\"arithmatex\">\\(O(m)\\)</span> klauzulemi, která je s <span class=\"arithmatex\">\\(\\varphi\\)</span> <strong>ekvisplnitelná</strong> (<span class=\"arithmatex\">\\(\\varphi\\)</span> splnitelná <span class=\"arithmatex\">\\(\\iff\\)</span> <span class=\"arithmatex\">\\(\\psi\\)</span> splnitelná).</p>","u":"@R/ch-resice-sat/ch-resice-sat-tseitinova-transformace.html#ch-resice-sat-thm-tseitin"},"prob-nae":{"t":"Problém 7.2: NAE-3-SAT","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\Phi\\)</span> v 3-CNF (každá klauzule má právě 3 literály).</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, při kterém v <em>žádné</em> klauzuli nemají všechny tři literály stejnou hodnotu?</p>","u":"@R/ch-sat/ch-sat-nae-3-sat-not-all-equal.html#prob-nae"},"lem-bitflip":{"t":"Lemma 7.3: Symetrie vůči negaci (bit-flip)","b":"<p>Pokud ohodnocení <span class=\"arithmatex\">\\(h\\)</span> NAE-splňuje <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\Phi\\)</span>,</span> pak ji NAE-splňuje i <span class=\"arithmatex\">\\(\\bar h\\)</span> (všechny hodnoty prohozeny <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(0\\leftrightarrow1\\)</span>).</span></p>","u":"@R/ch-sat/ch-sat-nae-3-sat-not-all-equal.html#lem-bitflip"},"thm-nae4":{"t":"Věta 7.4","b":"<p><span class=\"arithmatex\">\\(\\varphi\\)</span> je splnitelná <span class=\"arithmatex\">\\(\\iff\\)</span> <span class=\"arithmatex\">\\(\\varphi'\\)</span> je NAE-splnitelná.</p>","u":"@R/ch-sat/ch-sat-nae-3-sat-not-all-equal.html#thm-nae4"},"lem-3satkor":{"t":"Lemma 7.1: Korektnost rozseknutí","b":"<p>Klauzule <span class=\"arithmatex\">\\(C=(\\ell_1\\lor\\dots\\lor\\ell_k)\\)</span> je splněna ohodnocením <span class=\"arithmatex\">\\(h\\)</span> <span class=\"arithmatex\">\\(\\iff\\)</span> <span class=\"arithmatex\">\\(h\\)</span> lze rozšířit na <span class=\"arithmatex\">\\(z_1,\\dots,z_{k-3}\\)</span> tak, aby byly splněny všechny klauzule <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(C'\\)</span>.</span></p>","u":"@R/ch-sat/ch-sat-sat-3-sat.html#lem-3satkor"},"def-abeceda":{"t":"Definice 1.1: Abeceda, řetězce, jazyk","b":"<ul><li><strong>Abeceda</strong> <span class=\"arithmatex\">\\(\\Sigma\\)</span> je konečná neprázdná množina symbolů (typicky <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\{0,1\\}\\)</span>).</span></li><li><span class=\"arithmatex\">\\(\\Sigma^*\\)</span> je množina všech <strong>konečných řetězců</strong> nad <span class=\"arithmatex\">\\(\\Sigma\\)</span> (včetně prázdného <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\varepsilon\\)</span>).</span></li><li><strong>Jazyk</strong> je libovolná podmnožina <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L \\subseteq \\Sigma^*\\)</span>.</span></li></ul>\n<p>Obecně počítáme funkce <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f\\colon \\Sigma^*\\to\\Sigma^*\\)</span>.</span> Výpočet <em>jednoho bitu</em> <span class=\"arithmatex\">\\(g\\colon\\{0,1\\}^*\\to\\{0,1\\}\\)</span> odpovídá jazyku <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L_g = \\{x\\in\\{0,1\\}^* \\mid g(x)=1\\}\\)</span>.</span></p>","u":"@R/ch-ts/ch-ts-co-vlastne-pocitame-abecedy-jazyky-problemy.html#def-abeceda"},"def-instance":{"t":"Definice 1.2: Instance, velikost vstupu","b":"<ul><li><strong>Instance</strong> je libovolný řetězec vyhovující specifikaci vstupu (např. kódování grafu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\enc{G}\\)</span>).</span></li><li>Instance dělíme na <strong>ANO-instance</strong> a <strong>NE-instance</strong> podle odpovědi na otázku problému.</li><li><strong>Velikost vstupu</strong> je <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(n = |\\enc{G}|\\)</span>,</span> tedy délka <em>kódování</em> instance.</li></ul>","u":"@R/ch-ts/ch-ts-co-vlastne-pocitame-abecedy-jazyky-problemy.html#def-instance"},"prob-tsp":{"t":"Problém 1.3: Obchodní cestující (TSP)","b":"<p><strong>Vstup:</strong> úplný graf <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G=(V,E)\\)</span>,</span> váhy <span class=\"arithmatex\">\\(w\\colon E\\to\\N\\)</span> (a práh <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\in\\N\\)</span>).</span></p>\n<p><strong>Optimalizační verze:</strong> najdi hamiltonovskou kružnici s minimální celkovou váhou.</p>\n<p><strong>Rozhodovací verze:</strong> existuje v <span class=\"arithmatex\">\\(G\\)</span> hamiltonovská kružnice váhy nejvýše <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>?</span></p>","u":"@R/ch-ts/ch-ts-optimalizacni-vs-rozhodovaci-problemy.html#prob-tsp"},"cor-binsearch":{"t":"Důsledek 1.4: Rozhodovací a optimalizační verze jsou „stejně těžké“","b":"<p>Leží-li optimum v rozsahu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(0,\\dots,\\mathrm{MAX}\\)</span>,</span> stačí <span class=\"arithmatex\">\\(\\lceil\\log_2 \\mathrm{MAX}\\rceil\\)</span> volání rozhodovacího API. Jsou-li váhy zapsány binárně, je <span class=\"arithmatex\">\\(\\log_2 \\mathrm{MAX}\\)</span> nejvýše polynomiální ve velikosti vstupu, takže z hlediska polynomiálního času o nic nepřicházíme.</p>","u":"@R/ch-ts/ch-ts-optimalizacni-vs-rozhodovaci-problemy.html#cor-binsearch"},"def-dts":{"t":"Definice 1.5: Deterministický Turingův stroj","b":"<p>Deterministický Turingův stroj (DTS) je osmice <span class=\"woo-nobr\"><span class=\"arithmatex\">\\((Q,\\Sigma,G,B,k,\\delta,q_0,\\qhalt)\\)</span>,</span> kde</p>\n<ul><li><span class=\"arithmatex\">\\(Q\\)</span> je konečná množina <strong>vnitřních stavů</strong>,</li><li><span class=\"arithmatex\">\\(\\Sigma\\)</span> je konečná <strong>vstupní abeceda</strong>,</li><li><span class=\"arithmatex\">\\(G\\)</span> je konečná <strong>abeceda pásky</strong>, <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\Sigma \\subsetneq G\\)</span>,</span></li><li><span class=\"arithmatex\">\\(B\\in G\\setminus\\Sigma\\)</span> je <strong>prázdný symbol</strong> (blank, značíme <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\blank\\)</span>),</span></li><li><span class=\"arithmatex\">\\(k\\)</span> je <strong>počet pásek</strong>,</li><li><span class=\"arithmatex\">\\(\\delta\\colon Q\\times G^k \\to Q\\times G^k\\times\\{\\Lft,\\Stay,\\Rgt\\}^k\\)</span> je <strong>přechodová funkce</strong>,</li><li><span class=\"arithmatex\">\\(q_0\\)</span> je <strong>počáteční</strong> a <span class=\"arithmatex\">\\(\\qhalt\\)</span> <strong>koncový</strong> stav.</li></ul>","u":"@R/ch-ts/ch-ts-turinguv-stroj.html#def-dts"},"def-fm":{"t":"Definice 1.7: Funkce počítaná TS","b":"<p>TS <span class=\"arithmatex\">\\(M\\)</span> počítá funkci <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(f_M\\)</span>,</span> pokud pro každé <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x\\in\\Sigma^*\\)</span>:</span> je-li výpočet na <span class=\"arithmatex\">\\(x\\)</span> konečný, je <span class=\"arithmatex\">\\(f_M(x)\\)</span> obsah výstupu; cyklí-li výpočet na <span class=\"arithmatex\">\\(x\\)</span> donekonečna, <span class=\"arithmatex\">\\(f_M(x)\\)</span> <em>není definována</em>.</p>","u":"@R/ch-ts/ch-ts-turinguv-stroj.html#def-fm"},"thm-church":{"t":"Věta 1.8 (Churchova–Turingova teze)","b":"<p>Ke každému algoritmu existuje ekvivalentní Turingův stroj.</p>\n<p><em>Silná forma:</em> každý fyzikálně realizovatelný počítač lze simulovat TS s nejvýše <em>polynomiálním</em> zpomalením (možným protipříkladem jsou kvantové počítače).</p>","u":"@R/ch-ts/ch-ts-turinguv-stroj.html#thm-church"},"cor-uts":{"t":"Důsledek 1.9: Cena univerzálnosti","b":"<p>Univerzální stroj <span class=\"arithmatex\">\\(U\\)</span> simuluje <span class=\"arithmatex\">\\(T\\)</span> kroků libovolného stroje <span class=\"arithmatex\">\\(M\\)</span> v čase <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(O(T\\log T)\\)</span>.</span></p>","u":"@R/ch-ts/ch-ts-univerzalni-turinguv-stroj.html#cor-uts"},"thm-matijasevic":{"t":"Věta 2.7 (Matijaševič, 1970)","b":"<p>Hilbertův 10. problém je nerozhodnutelný.</p>","u":"@R/ch-vycisl/ch-vycisl-hilbertuv-10-problem.html#thm-matijasevic"},"def-uc":{"t":"Definice 2.2: Funkce <span class=\"arithmatex\">\\(\\prob{UC}\\)</span>","b":"<p>Pro <span class=\"arithmatex\">\\(\\alpha\\in\\{0,1\\}^*\\)</span> definujeme</p>\n<div class=\"arithmatex\">\\[\\mathrm{UC}(\\alpha)=\\begin{cases} 0 &amp; \\text{pokud $\\alpha$ je zápisem nějakého DTS $M_\\alpha$ a platí $M_\\alpha(\\alpha)=1$},\\\\ 1 &amp; \\text{jinak (tj. $\\alpha$ není zápis DTS, nebo se $M_\\alpha$ na $\\alpha$ zacyklí, nebo $M_\\alpha(\\alpha)\\neq 1$).} \\end{cases}\\]</div>","u":"@R/ch-vycisl/ch-vycisl-nepocitatelna-funkce-uc.html#def-uc"},"thm-ucnc":{"t":"Věta 2.3 (<span class=\"arithmatex\">\\(\\prob{UC}\\)</span> není počitatelná)","b":"<p>Neexistuje TS, který by počítal funkci <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\prob{UC}\\)</span>.</span></p>","u":"@R/ch-vycisl/ch-vycisl-nepocitatelna-funkce-uc.html#thm-ucnc"},"prob-halt":{"t":"Problém 2.4: <span class=\"arithmatex\">\\(\\prob{HaltingProblem}\\)</span>","b":"<p><strong>Vstup:</strong> popis TS <span class=\"arithmatex\">\\(\\enc{M}\\)</span> a vstupní řetězec <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x\\)</span>.</span></p>\n<p><strong>Otázka:</strong> zastaví se výpočet <span class=\"arithmatex\">\\(M\\)</span> na vstupu <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x\\)</span>?</span></p>","u":"@R/ch-vycisl/ch-vycisl-problem-zastaveni.html#prob-halt"},"thm-halting":{"t":"Věta 2.5 (O problému zastavení)","b":"<p>Jazyk <span class=\"arithmatex\">\\(\\mathrm{Halt}=\\{\\enc{M,x}\\mid M \\text{ zastaví na } x\\}\\)</span> je rekurzivně spočetný, ale není rekurzivní.</p>","u":"@R/ch-vycisl/ch-vycisl-problem-zastaveni.html#thm-halting"},"cor-analyzator":{"t":"Důsledek 2.6: Pro praxi","b":"<p>Nelze napsat univerzální analyzátor kódu, který by pro <em>libovolný</em> program s jistotou určil, zda nespadne do nekonečného cyklu.</p>","u":"@R/ch-vycisl/ch-vycisl-problem-zastaveni.html#cor-analyzator"},"def-rekurzivni":{"t":"Definice 2.1: Rekurzivní a rekurzivně spočetné jazyky","b":"<ul><li><strong>Jazyk stroje</strong> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(M\\)</span>:</span> <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L_M = \\{x\\in\\Sigma^* \\mid f_M(x)=1\\}\\)</span>.</span></li><li><span class=\"arithmatex\">\\(L\\)</span> je <strong>rekurzivně spočetný</strong>, pokud existuje TS <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(M\\)</span>,</span> který ho <em>přijímá</em> (<span class=\"woo-nobr\"><span class=\"arithmatex\">\\(L=L_M\\)</span>).</span> Na slovech mimo <span class=\"arithmatex\">\\(L\\)</span> se <span class=\"arithmatex\">\\(M\\)</span> smí zacyklit.</li><li><span class=\"arithmatex\">\\(L\\)</span> je <strong>rekurzivní (rozhodnutelný)</strong>, pokud existuje TS <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(M\\)</span>,</span> který ho přijímá <em>a zastaví se na každém vstupu</em>.</li><li>Jinak je <span class=\"arithmatex\">\\(L\\)</span> <strong>nerozhodnutelný</strong>.</li></ul>","u":"@R/ch-vycisl/index.html#def-rekurzivni"},"prob-1in3":{"t":"Problém 10.1: <span class=\"arithmatex\">\\(\\prob{One-in-Three 3-SAT}\\)</span> (1-in-3 SAT)","b":"<p><strong>Vstup:</strong> formule <span class=\"arithmatex\">\\(\\Phi\\)</span> v 3-CNF.</p>\n<p><strong>Otázka:</strong> existuje ohodnocení, při kterém je v každé klauzuli <em>přesně jeden</em> literál pravdivý?</p>","u":"@R/ch-x3c/ch-x3c-1-in-3-sat.html#prob-1in3"},"prob-x3c":{"t":"Problém 10.2: <span class=\"arithmatex\">\\(\\prob{X3C}\\)</span>","b":"<p><strong>Vstup:</strong> univerzum <span class=\"arithmatex\">\\(U\\)</span> s <span class=\"arithmatex\">\\(|U|=3k\\)</span> a systém <span class=\"arithmatex\">\\(\\mathcal S\\)</span> tříprvkových podmnožin <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(U\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze z <span class=\"arithmatex\">\\(\\mathcal S\\)</span> vybrat přesně <span class=\"arithmatex\">\\(k\\)</span> množin tak, aby byl každý prvek <span class=\"arithmatex\">\\(U\\)</span> pokryt <em>právě jednou</em>?</p>","u":"@R/ch-x3c/ch-x3c-exact-cover.html#prob-x3c"},"lem-x3c1":{"t":"Lemma 10.3: Splnitelná formule <span class=\"arithmatex\">\\(\\Rightarrow\\)</span> exaktní pokrytí","b":"<p>Je-li <span class=\"arithmatex\">\\(\\Phi\\)</span> splnitelná, má sestrojená instance X3C exaktní pokrytí.</p>","u":"@R/ch-x3c/ch-x3c-exact-cover.html#lem-x3c1"},"lem-x3c2":{"t":"Lemma 10.4: Exaktní pokrytí <span class=\"arithmatex\">\\(\\Rightarrow\\)</span> splnitelná formule","b":"<p>Má-li sestrojená instance X3C exaktní pokrytí, je <span class=\"arithmatex\">\\(\\Phi\\)</span> splnitelná.</p>","u":"@R/ch-x3c/ch-x3c-exact-cover.html#lem-x3c2"},"prob-3col":{"t":"Problém 9.1: 3-Coloring (3-barvení)","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G=(V,E)\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze vrcholy obarvit třemi barvami tak, aby žádná hrana nespojovala dva vrcholy stejné barvy?</p>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#prob-3col"},"lem-trojuhelnik":{"t":"Lemma 9.2: O trojúhelníku","b":"<ol><li>Mají-li vstupy stejnou barvu, má výstup <span class=\"arithmatex\">\\(c\\)</span> nutně <em>tutéž</em> barvu.</li><li>Mají-li vstupy různé barvy, lze <span class=\"arithmatex\">\\(c\\)</span> obarvit <em>libovolnou</em> ze tří barev.</li></ol>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#lem-trojuhelnik"},"thm-3sat3col":{"t":"Věta 9.3","b":"<p><span class=\"arithmatex\">\\(\\Phi\\)</span> je splnitelná <span class=\"arithmatex\">\\(\\iff\\)</span> <span class=\"arithmatex\">\\(G_\\Phi\\)</span> je 3-obarvitelný. Tedy <span class=\"arithmatex\">\\(\\prob{3-SAT}\\redp\\prob{3-Coloring}\\)</span> a <span class=\"arithmatex\">\\(\\prob{3-Coloring}\\)</span> je NP-úplný.</p>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#thm-3sat3col"},"prob-rozvrh":{"t":"Problém 9.4: Rozvrh zkoušek","b":"<p><strong>Vstup:</strong> množina předmětů, studenti se svými zápisy předmětů, číslo <span class=\"arithmatex\">\\(k\\)</span> (počet termínů).</p>\n<p><strong>Otázka:</strong> lze každému předmětu přidělit jeden z <span class=\"arithmatex\">\\(k\\)</span> termínů tak, aby žádný student neměl dvě zkoušky ve stejném termínu?</p>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#prob-rozvrh"},"def-intgraf":{"t":"Definice 9.5: Intervalový graf","b":"<p>Vrcholy jsou intervaly na přímce, hrana spojuje dva intervaly, které se překrývají.</p>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#def-intgraf"},"thm-greedyint":{"t":"Věta 9.6 (Hladové barvení intervalů je optimální)","b":"<p>Projdeme intervaly podle začátku a každému přiřadíme nejmenší barvu, kterou nemá žádný už obarvený překrývající se interval. Tento algoritmus použije přesně <span class=\"arithmatex\">\\(\\omega\\)</span> barev, kde <span class=\"arithmatex\">\\(\\omega\\)</span> je největší počet intervalů, které se překrývají v jednom bodě.</p>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#thm-greedyint"},"prob-planar":{"t":"Problém 9.7: Planar 3-Coloring","b":"<p><strong>Vstup:</strong> rovinný graf <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G\\)</span>.</span></p>\n<p><strong>Otázka:</strong> je <span class=\"arithmatex\">\\(G\\)</span> 3-obarvitelný?</p>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#prob-planar"},"thm-gjs":{"t":"Věta 9.8 (Garey, Johnson, Stockmeyer 1976)","b":"<p><span class=\"arithmatex\">\\(\\prob{Planar 3-Coloring}\\)</span> je NP-úplný.</p>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#thm-gjs"},"lem-krizeni":{"t":"Lemma 9.9: Gadget pro křížení","b":"<p>V každém 3-obarvení gadgetu je <span class=\"arithmatex\">\\(\\mathrm{barva}(x)=\\mathrm{barva}(x')\\)</span> a <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(\\mathrm{barva}(y)=\\mathrm{barva}(y')\\)</span>.</span> Naopak každé takové obarvení terminálů (i pro <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x=y\\)</span>,</span> i pro <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(x\\neq y\\)</span>)</span> lze do gadgetu doplnit. Gadget je rovinný a terminály <span class=\"arithmatex\">\\(x,y,x',y'\\)</span> leží na vnější stěně v tomto pořadí.</p>","u":"@R/ch-zoo/ch-zoo-3-coloring.html#lem-krizeni"},"prob-mapf":{"t":"Problém 9.13: Multiagent Path Finding (MAPF)","b":"<p><strong>Vstup:</strong> graf <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(G\\)</span>,</span> množina agentů <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(A\\)</span>;</span> každý agent <span class=\"arithmatex\">\\(a\\)</span> má start <span class=\"arithmatex\">\\(s(a)\\in V(G)\\)</span> a cíl <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(t(a)\\in V(G)\\)</span>;</span> číslo <span class=\"arithmatex\">\\(\\ell\\)</span> (<em>makespan</em>).</p>\n<p><strong>Otázka:</strong> lze všechny agenty dopravit do jejich cílů během <span class=\"arithmatex\">\\(\\ell\\)</span> kroků?</p>","u":"@R/ch-zoo/ch-zoo-mapf-hledani-cest-pro-vice-agentu.html#prob-mapf"},"thm-mapfnp":{"t":"Věta 9.14 (Složitost MAPF)","b":"<p>MAPF je NP-úplný i pro <span class=\"arithmatex\">\\(\\ell=3\\)</span> (se swapy i bez nich).</p>","u":"@R/ch-zoo/ch-zoo-mapf-hledani-cest-pro-vice-agentu.html#thm-mapfnp"},"lem-mapfvar":{"t":"Lemma 9.15: Všichni agenti volí stejně","b":"<p>V každém řešení s <span class=\"arithmatex\">\\(\\ell=3\\)</span> jdou buď <em>všichni</em> agenti <span class=\"arithmatex\">\\(a_1,\\dots,a_{m_x}\\)</span> přes <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(n_i\\)</span>,</span> nebo všichni přes <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(p_i\\)</span>.</span></p>","u":"@R/ch-zoo/ch-zoo-mapf-hledani-cest-pro-vice-agentu.html#lem-mapfvar"},"lem-blokator":{"t":"Lemma 9.16: O blokátoru","b":"<p>V každém řešení s <span class=\"arithmatex\">\\(\\ell=3\\)</span> jde aspoň jeden z agentů <span class=\"arithmatex\">\\(c_1,c_2,c_3\\)</span> vnější cestou.</p>","u":"@R/ch-zoo/ch-zoo-mapf-hledani-cest-pro-vice-agentu.html#lem-blokator"},"thm-mapfred":{"t":"Věta 9.17","b":"<p><span class=\"arithmatex\">\\(\\Phi\\)</span> je splnitelná <span class=\"arithmatex\">\\(\\iff\\)</span> existuje plán s makespanem 3.</p>","u":"@R/ch-zoo/ch-zoo-mapf-hledani-cest-pro-vice-agentu.html#thm-mapfred"},"prob-maxcut":{"t":"Problém 9.10: MaxCut (maximální řez)","b":"<p><strong>Vstup:</strong> neorientovaný graf <span class=\"arithmatex\">\\(G=(V,E)\\)</span> a číslo <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(k\\)</span>.</span></p>\n<p><strong>Otázka:</strong> lze rozdělit <span class=\"arithmatex\">\\(V=A\\cup B\\)</span> (disjunktně) tak, aby aspoň <span class=\"arithmatex\">\\(k\\)</span> hran mělo jeden konec v <span class=\"arithmatex\">\\(A\\)</span> a druhý v <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(B\\)</span>?</span></p>","u":"@R/ch-zoo/ch-zoo-maxcut.html#prob-maxcut"},"thm-naemaxcut":{"t":"Věta 9.11","b":"<p><span class=\"arithmatex\">\\(\\Phi\\)</span> je NAE-splnitelná <span class=\"arithmatex\">\\(\\iff\\)</span> <span class=\"arithmatex\">\\(G\\)</span> má řez váhy aspoň <span class=\"woo-nobr\"><span class=\"arithmatex\">\\(2mn+2m\\)</span>.</span></p>","u":"@R/ch-zoo/ch-zoo-maxcut.html#thm-naemaxcut"}};
